# ---- begin include rewrite/lib/rt.py ----
# Shared prepare-time runtime for campaign 2026-10-26-decode-first-rewrite (workstream W0).
# Everything here runs inside prepare() only (never inside kernel_fn), so host syncs are fine.
#   - read flush: the judge READS a buffer larger than L2 before each timed replay; zero_() writes and leaves
#     ~50 MB of dirty lines that the measured kernel then writes back (FINDINGS 3.2). _rt_read_flush reads.
#   - graph timing: interleaved, order-rotated replays, each preceded by a read flush, minus an empty-graph
#     baseline measured in the same interleave (the judge subtracts its fixed graph cost too).
#   - selection: a candidate replaces the incumbent only if every round on every routing clears the margin.
#   - checks: the judge's rel-L2 and per-row forms, against a reference the caller computes with the
#     candidate's OWN routing (never against master's output).
# Names are prefixed _rt_ / RT_ because this file is pasted into several single-file submissions.

RT_FLUSH_BYTES = 256 * 1024 * 1024
RT_REPS = 41
RT_ROUNDS = 2
RT_MARGIN = 1.03             # every round, every routing: incumbent / candidate >= this ...
RT_MARGIN_TIGHT_IQR = 1.02   # ... or >= this when the candidate IQR <= RT_IQR_FACTOR x the incumbent's
RT_IQR_FACTOR = 1.5
RT_IQR_FLOOR_US = 0.5
RT_JUDGE_REL = 1.5e-2        # TASK.md: output rel-L2 vs the fp32 reference
RT_ROW_FACTOR = 5.0          # TASK.md: any single row at most 5 x the bound (tenth-of-mean-row floor)
RT_CHECK_FRACTION = 0.5      # our gates use half the judge's bound

_RT_FLUSH = {}


def _rt_flush_buf(device):
    key = str(device)
    if key not in _RT_FLUSH:
        _RT_FLUSH[key] = torch.zeros(RT_FLUSH_BYTES // 4, dtype=torch.float32, device=device)
    return _RT_FLUSH[key]


def _rt_read_flush(device):
    """Read 256 MB (a full reduction into one value), leaving L2 full of clean lines, as the judge does."""
    return torch.sum(_rt_flush_buf(device))


def _rt_write_flush(device):
    """The repo's old flush (zero_ = a 256 MB write); kept only to measure the dirty-L2 penalty."""
    _rt_flush_buf(device).zero_()


def _rt_graph(fn, warm=2):
    """Capture fn() as a CUDA graph after `warm` eager calls on a side stream. Returns (graph, output)."""
    s = torch.cuda.Stream()
    s.wait_stream(torch.cuda.current_stream())
    with torch.cuda.stream(s):
        for _ in range(warm):
            fn()
    torch.cuda.current_stream().wait_stream(s)
    torch.cuda.synchronize()
    g = torch.cuda.CUDAGraph()
    with torch.cuda.graph(g):
        out = fn()
    torch.cuda.synchronize()
    return g, out


def _rt_stats(samples):
    """(median, IQR, p10, p90) of a list."""
    s = sorted(samples)
    n = len(s)
    if n == 0:
        return float("nan"), float("nan"), float("nan"), float("nan")
    return s[n // 2], s[(3 * n) // 4] - s[n // 4], s[n // 10], s[min(n - 1, (9 * n) // 10)]


_RT_EMPTY = {}


def _rt_empty_graph(device):
    key = str(device)
    if key not in _RT_EMPTY:
        t = torch.zeros(1, dtype=torch.float32, device=device)
        g, _ = _rt_graph(lambda: t.add_(0.0))
        _RT_EMPTY[key] = (g, t)
    return _RT_EMPTY[key][0]


def _rt_time(graphs, device, reps=RT_REPS, rounds=RT_ROUNDS, flush="read", baseline=True):
    """Interleaved cold-L2 timing of {name: CUDAGraph}. Each replay is preceded by a flush (read by default) and
    bracketed by CUDA events; the order rotates every rep and flips every other. With baseline=True an empty
    graph is timed in the same interleave and its median is subtracted from every sample of that round.
    Returns [ {name: [us, ...]} per round ]."""
    names = list(graphs)
    gs = dict(graphs)
    if baseline:
        gs["__empty__"] = _rt_empty_graph(device)
    order0 = list(gs)
    for _ in range(2):
        for n in order0:
            gs[n].replay()
    torch.cuda.synchronize()
    out = []
    for r in range(rounds):
        ts = {n: [] for n in order0}
        for rep in range(reps):
            k = rep % len(order0)
            order = order0[k:] + order0[:k]
            if (rep + r) % 2:
                order = order[::-1]
            for n in order:
                if flush == "read":
                    _rt_read_flush(device)
                elif flush == "write":
                    _rt_write_flush(device)
                s_, e_ = torch.cuda.Event(enable_timing=True), torch.cuda.Event(enable_timing=True)
                s_.record()
                gs[n].replay()
                e_.record()
                e_.synchronize()
                ts[n].append(s_.elapsed_time(e_) * 1000.0)
        if baseline:
            b = _rt_stats(ts.pop("__empty__"))[0]
            ts = {n: [v - b for v in vs] for n, vs in ts.items()}
            ts["__baseline_us__"] = [b]
        out.append(ts)
    return out


def _rt_select(rounds_by_routing, incumbent, candidates, margin=RT_MARGIN, tight=RT_MARGIN_TIGHT_IQR,
               prefer_within=0.0):
    """Decide among candidates from {routing: _rt_time(...) result}. A candidate qualifies only if in EVERY round
    on EVERY routing: incumbent_med / cand_med >= margin, or >= tight with cand IQR <= RT_IQR_FACTOR x the
    incumbent's (floored). Returns (winner or None, {cand: worst ratio}, [lines])."""
    worst = {c: float("inf") for c in candidates}
    ok = {c: True for c in candidates}
    lines = []
    for rlabel, rounds in rounds_by_routing.items():
        for ri, ts in enumerate(rounds):
            im, ii, _, _ = _rt_stats(ts[incumbent])
            parts = [f"{incumbent} {im:.2f} us (IQR {ii:.2f})"]
            for c in candidates:
                cm, ci, p10, p90 = _rt_stats(ts[c])
                ratio = im / max(cm, 1e-3)
                iqr_ok = ci <= RT_IQR_FACTOR * max(ii, RT_IQR_FLOOR_US)
                passed = ratio >= margin or (ratio >= tight and iqr_ok)
                worst[c] = min(worst[c], ratio)
                ok[c] = ok[c] and passed
                parts.append(f"{c} {cm:.2f} us (IQR {ci:.2f}, p10/p90 {p10:.2f}/{p90:.2f}, x{ratio:.3f}"
                             f"{'' if passed else ', FAIL'})")
            base = ts.get("__baseline_us__", [float("nan")])[0]
            lines.append(f"{rlabel} round {ri + 1} (graph baseline {base:.2f} us subtracted): " + " | ".join(parts))
    good = [c for c in candidates if ok[c]]
    win = max(good, key=lambda c: worst[c]) if good else None
    if win is not None and prefer_within > 0:  # the earliest qualifying candidate within prefer_within of the best
        win = next(c for c in candidates if c in good and worst[c] >= worst[win] * (1.0 - prefer_within))
    return win, worst, lines


def _rt_rel(a, b):
    """Relative L2 |a - b| / |b| in float64."""
    a64, b64 = a.double(), b.double()
    den = float(b64.norm())
    num = float((a64 - b64).norm())
    if den == 0.0:
        return 0.0 if num == 0.0 else float("inf")
    return num / den


def _rt_row_rel(out, ref):
    """Worst row of |out - ref| / max(|ref row|, a tenth of the mean ref row): the judge's per-row form."""
    o, r = out.double().reshape(out.shape[0], -1), ref.double().reshape(ref.shape[0], -1)
    rn = r.norm(dim=-1)
    den = torch.maximum(rn, 0.1 * rn.mean()).clamp_min(1e-30)
    return float(((o - r).norm(dim=-1) / den).max())


def _rt_check(out, ref, judge_rel=RT_JUDGE_REL, fraction=RT_CHECK_FRACTION):
    """(ok, rel, worst_row, text) with bounds fraction x the judge's: rel-L2 <= fraction x judge_rel and the worst
    row <= fraction x RT_ROW_FACTOR x judge_rel; out must be finite. ref must come from the candidate's own routing."""
    o = out.float()
    finite = bool(torch.isfinite(o).all())
    if not finite:
        bad = int((~torch.isfinite(o)).sum())
        return False, float("inf"), float("inf"), f"NON-FINITE ({bad} values)"
    rel = _rt_rel(o, ref)
    row = _rt_row_rel(o, ref)
    lim, rlim = fraction * judge_rel, fraction * RT_ROW_FACTOR * judge_rel
    ok = rel <= lim and row <= rlim
    return ok, rel, row, f"rel-L2 {rel:.3g} (<= {lim:.3g}), worst row {row:.3g} (<= {rlim:.3g})"


def _rt_tracer(tag, label):
    """prepare()-only launch tracer for canaries: device sync then a flushed print, so a fault names its launch."""
    def _step(what):
        torch.cuda.synchronize()
        print(f"{tag}     [{label}] {what}", flush=True)
    return _step


def _rt_build(tag, name, cpp, cuda, functions, arch="9.0a", extra=()):
    """load_inline for sm_90a only (TORCH_CUDA_ARCH_LIST set around the build, restored after), with
    -O3 -std=c++20 -lineinfo. Returns (ext or None, error text, seconds)."""
    t0 = time.perf_counter()
    prev = os.environ.get("TORCH_CUDA_ARCH_LIST")
    flags = ["-O3", "-std=c++20", "-lineinfo"] + list(extra)
    ext, err = None, ""
    try:
        from torch.utils.cpp_extension import load_inline
        os.environ["TORCH_CUDA_ARCH_LIST"] = arch
        ext = load_inline(name=name, cpp_sources=cpp, cuda_sources=cuda, functions=list(functions),
                          extra_cuda_cflags=flags, verbose=False)
    except Exception as e:
        err = str(e)
        # The exception carries the whole build log; keep the compiler's error lines (the useful part).
        errs = [ln.strip()[:240] for ln in err.splitlines() if "error" in ln.lower() and "Error building" not in ln]
        err = " || ".join(errs[:8]) if errs else err[-600:]
        print(f"{tag} load_inline {name} failed after {time.perf_counter() - t0:.1f}s: {err!r}", flush=True)
    finally:
        if prev is None:
            os.environ.pop("TORCH_CUDA_ARCH_LIST", None)
        else:
            os.environ["TORCH_CUDA_ARCH_LIST"] = prev
    dt = time.perf_counter() - t0
    if ext is not None:
        print(f"{tag} load_inline {name} compiled in {dt:.1f}s (TORCH_CUDA_ARCH_LIST={arch}, {flags})", flush=True)
    return ext, err, dt
