# ---- begin include rewrite/lib/ea_core.py ----
# Engine A core (campaign 2026-10-26-decode-first-rewrite, workstream W2): problem-agnostic pieces shared by the
# moe and decode submissions. Engine A runs this GPU's NVFP4 expert block for 1 <= T <= 8 tokens as two hand-written
# launches (ea_w13: w13 + silu; ea_w2: w2, PDL on ea_w13) plus the problem's Triton post-norm combine. A CTA-shared
# ring of 18 KB 1-D bulk stages feeds mma.sync swap-AB consumers that dequantize the NVFP4 codes exactly in registers
# (the integer scale path when every scale byte is a positive normal E4M3 value, else master's cvt path); stream-K
# balance with a last-arriver ticket, no spins. Weights are a lossless permutation of the same codes and scale bytes,
# repacked in prepare. Adapters (ea_moe.py, ea_decode.py) own the canary, the selector and the state copy check.
EA_MAX_T = 8

EA_CTAS_PER_SM = 2

EA_LAYOUT_NAME = {1: "master cvt dequant", 2: "exact integer dequant"}

def _ea_luts(device):
    """int64 [3][4 pairs][2 halves][16 codes]: the bits of one E2M1 code inside a 32-bit A-fragment word.
    Index 1 = master layout (pair p: low element at nibble 3 - p, high at nibble 7 - p; ext_master),
    index 2 = proposed layout (pairs 0..2 at bits {6,7,8,15} - 3p, pair 3 in the leftover bits; ext_prop)."""
    lut = torch.zeros((3, 4, 2, 16), dtype=torch.int64)
    for c in range(16):
        for p in range(4):
            for half in range(2):
                lut[1, p, half, c] = c << (4 * ((3 - p) + 4 * half))
                if p < 3:
                    v = ((c & 7) << (6 - 3 * p)) | ((c >> 3) << (15 - 3 * p))
                else:
                    v = (((c >> 1) & 3) << 10) | ((c & 1) << 13) | ((c >> 3) << 14)
                lut[2, p, half, c] = v << (16 * half)
    return lut.to(device)

def _ea_pack(tile_nib, tile_sf, lut):
    """tile_nib uint8 [NG, 4, 2, 8, K] codes 0..15 (group, warp, row half, g), tile_sf uint8 [NG, 4, 2, 8, K/16] raw
    E4M3 bytes -> uint8 [NG, K/512, 4, 4608] warp records: 4096 B of A-fragment words (uint4 index
    ((rh * 4 + kq) * 32 + g * 4 + c), word wd: row rh * 8 + g, k16 blocks kq * 8 + 2 wd + bsel, elements 2c + {0,1}
    (pair 2 bsel) and 2c + 8 + {0,1} (pair 2 bsel + 1)) then 512 B of scales [row][32 blocks]. Lossless."""
    ng, k = tile_nib.shape[0], tile_nib.shape[-1]
    nk = k // 512
    t = tile_nib.reshape(ng, 4, 2, 8, nk, 4, 4, 2, 2, 4, 2).long()  # gi w rh g kc kq wd bsel hi c el
    words = torch.zeros((ng, 4, 2, 8, nk, 4, 4, 4), dtype=torch.int64, device=tile_nib.device)  # gi w rh g kc kq wd c
    for bsel in range(2):
        for hi in range(2):
            p = 2 * bsel + hi
            for el in range(2):
                words |= lut[p, el][t[:, :, :, :, :, :, :, bsel, hi, :, el]]
    del t
    w = words.permute(0, 4, 1, 2, 5, 3, 7, 6).contiguous()  # gi kc w rh kq g c wd
    del words
    codes = torch.stack([(w >> (8 * i)) & 0xFF for i in range(4)], dim=-1).to(torch.uint8).reshape(ng, nk, 4, 4096)
    sc = tile_sf.reshape(ng, 4, 2, 8, nk, 32).permute(0, 4, 1, 2, 3, 5).reshape(ng, nk, 4, 512)
    return torch.cat((codes, sc), dim=-1).contiguous()

def _ea_scales_ok(weights, start, count):
    """The integer scale path needs every block-scale byte in [0x08, 0x7E] (positive normal E4M3, not NaN)."""
    for key in ("w13_sf", "w2_sf"):
        b = weights[key][start:start + count].contiguous().view(torch.uint8)
        if not bool(((b >= 0x08) & (b <= 0x7E)).all()):
            return False
    return True

def _ea_repack(weights, start, count, dq):
    """Lossless Engine A repack of experts [start, start + count) of the weight tensors: w13 as 64-row groups of 4 warp
    records (each 8 gate rows + the 8 matching up rows), w2 as 64-row groups of 16-row records; global scales fp32
    with the dequant bias 2^7 folded. Problem-agnostic (moe holds 256 experts, decode its 32 local ones)."""
    inter = weights["w13"].shape[1] // 2
    hidden = weights["w2"].shape[1]
    dev = weights["w13"].device
    lut = _ea_luts(dev)[dq]
    w13r = torch.empty((count, inter // 32, hidden // 512, 4, 4608), dtype=torch.uint8, device=dev)
    w2r = torch.empty((count, hidden // 64, inter // 512, 4, 4608), dtype=torch.uint8, device=dev)
    for i in range(count):
        e = start + i
        nib = _ea_nibbles(weights["w13"][e].contiguous())          # [2I, H]
        sf = weights["w13_sf"][e].contiguous().view(torch.uint8)   # [2I, H / 16]
        tile = torch.stack((nib[:inter].reshape(inter // 32, 4, 8, hidden),
                            nib[inter:].reshape(inter // 32, 4, 8, hidden)), dim=2)
        stile = torch.stack((sf[:inter].reshape(inter // 32, 4, 8, -1), sf[inter:].reshape(inter // 32, 4, 8, -1)), dim=2)
        w13r[i] = _ea_pack(tile, stile, lut)
        del nib, sf, tile, stile
        nib = _ea_nibbles(weights["w2"][e].contiguous())           # [H, I]
        sf = weights["w2_sf"][e].contiguous().view(torch.uint8)    # [H, I / 16]
        w2r[i] = _ea_pack(nib.reshape(hidden // 64, 4, 2, 8, inter), sf.reshape(hidden // 64, 4, 2, 8, -1), lut)
        del nib, sf
    sl = slice(start, start + count)
    return {"w13r": w13r.reshape(-1), "w2r": w2r.reshape(-1),
            "gs13": (weights["w13_gs"][sl].float() * 128.0).contiguous(),
            "gs2": (weights["w2_gs"][sl].float() * 128.0).contiguous()}

def _ea_forward_core(ea, x, topk_ids, topk_weights, start, count, norm_w, trace=None, pdl13=0):
    """out [T, H] for 1 <= T <= EA_MAX_T: ea_w13 (device work map + w13 + silu -> h [32, T, I]; local_ids [T, 8]),
    ea_w2 (PDL on ea_w13 -> y in master's cache3 layout), then the problem's _post_norm_combine_kernel (the same
    Triton kernel in moe and decode). topk_ids [T, 8] int32: an id is local iff start <= id < start + count.
    pdl13: launch ea_w13 with the PDL attribute (decode: it follows the routing kernel)."""
    ext = ea["ext"]
    tokens, hidden = x.shape
    inter = ea["inter"]
    h = torch.empty((32, tokens, inter), device=x.device, dtype=torch.bfloat16)
    local_ids = torch.empty((tokens, TOP_K), device=x.device, dtype=torch.int32)
    y = torch.empty((tokens * TOP_K, hidden), device=x.device, dtype=torch.bfloat16)
    if trace is not None:
        trace("before ea_w13")
    pf = ea.get("pf_t", {}).get(tokens, 0)
    if pf:  # K1 also pulls the active experts' w2 records into L2 for K2 (few active experts)
        ext.ea_w13_pf(x, topk_ids, ea["w13r"], ea["gs13"], h, local_ids, ea["ws13"], ea["tk13"], ea["err"], tokens,
                      start, count, ea["grid"], ea["dq"], pdl13, ea["w2r"], pf)
    else:
        ext.ea_w13(x, topk_ids, ea["w13r"], ea["gs13"], h, local_ids, ea["ws13"], ea["tk13"], ea["err"], tokens,
                   start, count, ea["grid"], ea["dq"], pdl13)
    if trace is not None:
        trace("after ea_w13 / before ea_w2")
    ext.ea_w2(h, topk_ids, ea["w2r"], ea["gs2"], y, ea["ws2"], ea["tk2"], ea["err"], tokens, start, count,
              ea.get("g2_t", {}).get(tokens, ea["grid"]), ea["dq"], ea["pdl"])
    if trace is not None:
        trace("after ea_w2 / before post-expert norm")
    out = torch.empty((tokens, hidden), device=x.device, dtype=torch.bfloat16)
    tw32 = topk_weights.to(torch.float32).contiguous()
    if ea.get("cmb_t", {}).get(tokens, 0):  # CUDA twin of the Triton combine, PDL-linked to K2
        ext.ea_combine(y, local_ids, tw32, norm_w, out, POST_NORM_EPS, 1)
    else:
        _post_norm_combine_kernel[(tokens,)](
            y, local_ids, tw32, norm_w, out, hidden, POST_NORM_EPS,
            TOP_K_C=TOP_K, BLOCK_H=triton.next_power_of_2(hidden), num_warps=8)
    if trace is not None:
        trace("after post-expert norm")
    return out


def _ea_nibbles(packed):
    """uint8 [..., n] -> uint8 [..., 2n]: element 2i is the low nibble, as nvfp4 packs."""
    return torch.stack((packed & 0x0F, packed >> 4), dim=-1).flatten(-2)


def _ea_buffers(device, grid, inter):
    """Per-state scratch: stream-K partials and tickets for both launches, the error word."""
    return {"inter": inter,
            "ws13": torch.zeros(grid * 1024, dtype=torch.float32, device=device),
            "tk13": torch.zeros(32 * 128, dtype=torch.int32, device=device),
            "ws2": torch.zeros(grid * 1024, dtype=torch.float32, device=device),
            "tk2": torch.zeros(32 * 64, dtype=torch.int32, device=device),
            "err": torch.zeros(4, dtype=torch.int32, device=device)}


def _ea_dequant(packed, sf, gs):
    """fp32 dequant of one expert matrix (E2M1 grid x E4M3 block scale x global scale)."""
    nib = _ea_nibbles(packed).long()
    grid = torch.tensor((0.0, 0.5, 1.0, 1.5, 2.0, 3.0, 4.0, 6.0), dtype=torch.float32, device=packed.device)
    mag = grid[nib & 7]
    val = torch.where((nib & 8) != 0, -mag, mag)
    rows, k = val.shape
    return (val.view(rows, k // 16, 16) * (sf.float() * gs.float()).unsqueeze(-1)).view(rows, k)


def _ea_ref_block(weights, base, x, lids, tw, norm_w, eps):
    """The expert block fully in fp32: lids [T, 8] local ids (-1 remote) index weights[...][base + id]; h and y in fp32;
    post-norm out[t] = sum over local slots of g * rmsnorm(y * (1 + w))."""
    tokens, hidden = x.shape
    inter = weights["w13"].shape[1] // 2
    flat = lids.reshape(-1).long()
    y = torch.zeros((tokens * TOP_K, hidden), dtype=torch.float32, device=x.device)
    for e in sorted(set(flat.tolist()) - {-1}):
        g = base + e
        w13 = _ea_dequant(weights["w13"][g], weights["w13_sf"][g], weights["w13_gs"][g])
        w2 = _ea_dequant(weights["w2"][g], weights["w2_sf"][g], weights["w2_gs"][g])
        rts = (flat == e).nonzero().flatten()
        hh = x[rts // TOP_K].float() @ w13.T
        h = torch.nn.functional.silu(hh[:, :inter]) * hh[:, inter:]
        y[rts] = h @ w2.T
        del w13, w2
    v = y.view(tokens, TOP_K, hidden) * (norm_w.float() + 1.0)
    loc = lids >= 0
    v = torch.where(loc.unsqueeze(-1), v, torch.zeros_like(v))
    r = torch.rsqrt(v.pow(2).mean(-1, keepdim=True) + eps)
    gw = torch.where(loc, tw.float(), torch.zeros_like(tw.float()))
    return (v * r * gw.unsqueeze(-1)).sum(1)


def _ea_cmb_check(ext, w, device):
    """The CUDA combine (ea_combine) against the problem's Triton _post_norm_combine_kernel on identical inputs at
    T = 1, 8, 16, 32: random y rows, local ids with remote (-1) slots and one token without a local slot, normalised
    weights. Passes when every T's rel-L2 <= 1e-3 and the token without a local slot is exactly zero. Returns
    (ok, line)."""
    gen = torch.Generator().manual_seed(20261034)
    worst, ok = 0.0, True
    for tokens in (1, 8, 16, 32):
        y = torch.randn((tokens * TOP_K, 4096), generator=gen).to(torch.bfloat16).to(device)
        ids = torch.randint(-1, 32, (tokens, TOP_K), generator=gen, dtype=torch.int32)
        ids[0, 0] = 5
        if tokens > 1:
            ids[-1, :] = -1
        ids = ids.to(device).contiguous()
        tw = torch.rand((tokens, TOP_K), generator=gen)
        tw = (tw / tw.sum(-1, keepdim=True)).to(device).contiguous()
        ref = torch.empty((tokens, 4096), device=device, dtype=torch.bfloat16)
        got = torch.full((tokens, 4096), float("nan"), device=device, dtype=torch.bfloat16)
        _post_norm_combine_kernel[(tokens,)](y, ids, tw, w, ref, 4096, POST_NORM_EPS, TOP_K_C=TOP_K, BLOCK_H=4096,
                                             num_warps=8)
        ext.ea_combine(y, ids, tw, w, got, POST_NORM_EPS, 1)
        torch.cuda.synchronize()
        rel = _rt_rel(got.float(), ref.float())
        worst = rel if rel != rel else max(worst, rel)  # a NaN must show
        ok = ok and rel <= 1e-3 and (tokens == 1 or bool((got[-1].float() == 0).all()))
    return ok, f"combine check (CUDA vs Triton, T 1/8/16/32): worst rel-L2 {worst:.3g} -> {'ok' if ok else 'FAIL'}"
