def _ea5_split(rec, count, ng):
    """v3 records (uint8, count x ng x 8 x 4 x 4608: [expert][64-row group][512-k chunk][warp][4096 B codes + 512 B
    scales]) -> v5 records (count x ng/2 x 16 x 2 x 4 x 2304: [expert][128-row super-group][256-k chunk][group of the
    pair][warp][2048 B codes + 256 B scales]). A warp record's codes are uint4 words ((rh * 4 + kq) * 32 + lane) for
    kq < 4; the 256-k half h keeps kq = 2 h + kq' as ((rh * 2 + kq') * 32 + lane), and its scales are blocks
    16 h .. 16 h + 15 of each of the 16 rows. Only bytes move."""
    r = rec.view(count, ng, 8, 4, 4608)
    codes = r[..., :4096].reshape(count, ng, 8, 4, 2, 2, 2, 512)          # e g kc w rh h kq' bytes
    codes = codes.permute(0, 1, 2, 5, 3, 4, 6, 7).reshape(count, ng, 8, 2, 4, 2048)   # e g kc h w (rh kq' bytes)
    scales = r[..., 4096:].reshape(count, ng, 8, 4, 16, 2, 16)              # e g kc w row h blk
    scales = scales.permute(0, 1, 2, 5, 3, 4, 6).reshape(count, ng, 8, 2, 4, 256)    # e g kc h w (row blk)
    v5 = torch.cat((codes, scales), dim=-1).reshape(count, ng // 2, 2, 16, 4, 2304)  # e sg pair (kc h) w rec
    return v5.permute(0, 1, 3, 2, 4, 5).contiguous().reshape(-1)                      # e sg kc5 pair w rec


def _ea5_repack(ea, count):
    """v5's records from v3's (ea["w13r"] / ea["w2r"], already on the device): a reshape / permute of the same bytes
    (audit: a numpy replay of _ea5_split matched the kernel's addressing with 0 mismatches; the canary against the fp32
    block checks it on the judge). Returns {"w13r5", "w2r5"}."""
    out = {}
    for key, ng in (("w13r", 2 * ea["inter"] // 64), ("w2r", ea["w2r"].numel() // (count * 8 * 4 * 4608))):
        src = ea[key]
        v5 = _ea5_split(src, count, ng)
        if v5.numel() != src.numel():
            raise RuntimeError(f"v5 repack of {key}: size differs")
        out[key + "5"] = v5
    return out


def _ea5_drop_unused(ea):
    """After the gates: v5's records (+0.9 GB, carried by every state copy) go when no T runs v5."""
    if "v5" not in set(ea.get("on", {}).values()):
        ea.pop("w13r5", None)
        ea.pop("w2r5", None)


def _ea5_forward_core(ea, x, topk_ids, topk_weights, start, count, norm_w, trace=None, pdl13=0):
    """_ea3_forward_core's contract on v5's kernels (ea5_w13 / ea5_w2) and records (w13r5 / w2r5)."""
    return _ea3_forward_core(ea, x, topk_ids, topk_weights, start, count, norm_w, trace, pdl13,
                             ("ea5_w13", "ea5_w2"), ("w13r5", "w2r5"))
# ---- end include rewrite/lib/ea5_core.py ----
# ---- begin include rewrite/lib/ea_moe.py ----
# Engine A moe adapter (campaign 2026-10-26-decode-first-rewrite, W2): canary, selector and state copy check for
# muse_moe_w4a16's kernel_fn (global expert ids, the bank's local range). One module (ea2_core.py) holds v1 (T <= 8,
# B = all T token rows), v2 (T <= 32, gathered B, passes of <= 8 routes per expert) and v3 (passes of <= 16 routes,
# two n8 tiles); each selector class picks master, v1, v2 or v3. Needs ea_core.py, ea2_core.py and ea3_core.py.

EA_TAG = "[engineA]"

EA_EXT_NAME = "okc_campaign_engine_a_v2"

EA_START_DEADLINE_S = 175.0   # build + repack + canary start only before this many s into prepare()

EA_GATE_DEADLINE_S = 240.0    # the selector starts only before this

EA_COPY_DEADLINE_S = 262.0    # the two-state copy check starts only before this

EA_BIG = (128, 256)           # exact-T classes for Engine A alone (verify 16 / 32); every other T > 32 stays on master

EA_COPY_TOL = 1e-4            # graph replay on a state copy vs eager kernel_fn (Engine A sums in a fixed order)

EA_JUDGE_DRAWS = 15           # reference-style draws per big-T selector; timed at their p10 / p50 / p90 of v3 passes
EA_BIG_ENGINES = ("v3", "v4", "v4c", "v5")   # big-T candidates (expert-bandwidth: v4 = v3 on 8 consumer warps, v5 = v4
                                      # with 32-route passes on 256-k records)
EA_PIN = {8: "v4", 16: "v4"}  # carrier (H100 M456, ties -> R10): class 8 (T=2..8) and class 16 (T=9..16) route this
                              # engine whenever it is canary-clean (per-T canary and copy check still guard it); {} = race
EA_CMB_PIN = {128: "v4c"}     # carrier (M456 c128v4ccuda x1.0112 / x1.0096): the CUDA combine at T=128 when the big gate
                              # routes this engine and the combine check passed (verify and copy check still guard it)

def _ea_forward(x, topk_ids, topk_weights, bank, state, trace=None, engine=None):
    """moe adapter: this GPU's expert block through Engine A (ids are global, the bank's range is local); engine 'v1'
    or 'v2', by default this T's prepare-set choice."""
    ea = state["ea"]
    core = {"v1": _ea_forward_core, "v2": _ea2_forward_core, "v3": _ea3_forward_core,
            "v4": _ea4_forward_core, "v4c": _ea4c_forward_core, "v5": _ea5_forward_core,
            "v6": _ea6_forward_core, "v6s": _ea6s_forward_core}[engine or ea["on"][x.shape[0]]]
    return core(ea, x, topk_ids, topk_weights, bank["start"], bank["count"], state["post_norm_w"], trace)

def _ea_cfg(bank, tokens, hidden):
    return {"bs": tokens, "d_hidden": hidden, "d_expert": bank["size_n"], "n_experts": N_EXPERTS,
            "local_start": bank["start"], "local_count": bank["count"], "top_k": TOP_K, "sharding": "ep8"}

def _ea_routings(tokens, gen, local_set, device):
    """[(label, topk_ids [T, 8] int32)]: judge-like zipf, random, 8 local experts per token, 4 hot local experts, one
    local expert, two local experts, no local expert, and (T >= 2) as many distinct local experts as 8 T allows."""
    remote = [e for e in range(N_EXPERTS) if e not in set(local_set)]
    nl = len(local_set)

    def pick_remote(k):
        return [remote[i] for i in torch.randperm(len(remote), generator=gen)[:k].tolist()]

    out = list(_combo_routings(tokens, gen, local_set, "cpu").items())
    rk = torch.arange(1, nl + 1, dtype=torch.float32) ** (-0.9)
    pop = torch.empty(nl, dtype=torch.float32)
    pop[torch.randperm(nl, generator=gen)] = rk
    pick = torch.multinomial(pop.expand(tokens, nl).contiguous(), TOP_K, replacement=False, generator=gen)
    out.append(("local8", torch.tensor(local_set, dtype=torch.int32)[pick]))
    out.append(("skewed-4hot", torch.tensor(_wg_routing("skewed-4hot", tokens, gen, local_set, remote), dtype=torch.int32)))
    two = torch.randperm(nl, generator=gen)[:2].tolist()
    e0, e1 = local_set[two[0]], local_set[two[1]]
    out.append(("one-local", torch.tensor([[e0] + pick_remote(7) for _ in range(tokens)], dtype=torch.int32)))
    out.append(("two-local", torch.tensor([[e0, e1] + pick_remote(6) for _ in range(tokens)], dtype=torch.int32)))
    out.append(("zero-local", torch.tensor([pick_remote(TOP_K) for _ in range(tokens)], dtype=torch.int32)))
    if tokens >= 2:
        out.append(("max-active", torch.tensor([[local_set[(8 * t + j) % nl] for j in range(TOP_K)]
                                                for t in range(tokens)], dtype=torch.int32)))
    return [(lab, ids.to(device).contiguous()) for lab, ids in out]

def _ea_judge_routings(tokens, gen, start, count, device):
    """{label: ids [tokens, 8] int32} for the big-T selectors (campaign expert-bandwidth X0a): of EA_JUDGE_DRAWS
    reference-style draws (_eb_ref_ids, dist normal, this GPU on the busiest range), the p10 / p50 / p90 by v3 passes
    (the sum over local experts of ceil(routes / 16)). Each label carries touched / max / local routes / passes."""
    draws = []
    for _ in range(EA_JUDGE_DRAWS):
        ids = _eb_ref_ids(tokens, gen, "normal", start, count)
        loc = ids.long().flatten() - start
        cnt = torch.bincount(loc[(loc >= 0) & (loc < count)], minlength=count)
        draws.append((int(((cnt + 15) // 16).sum()), int((cnt > 0).sum()), int(cnt.max()), int(cnt.sum()), ids))
    draws.sort(key=lambda d: d[0])
    out = {}
    for tag, i in (("p10", 1), ("p50", EA_JUDGE_DRAWS // 2), ("p90", EA_JUDGE_DRAWS - 2)):
        passes, touched, mx, routes, ids = draws[i]
        out[f"judge {tag} ({touched} experts, max {mx}, {routes} routes, {passes} passes)"] = ids.to(device).contiguous()
    return out


def _ea_canary(weights, bank, state, device, t_prepare):
    """Untimed, eager, synced. Every T in 1..EA2_MAX_T on every routing with every engine that takes T: finite, error
    word 0, rel-L2 and worst row against the fp32 reference within half the judge's bounds (_rt_check), exact zeros
    without local routes, and no worse than 2x master's own error. The first launch of each engine is traced.
    Returns ({T: {engine: bool}}, [FAIL lines], [one summary line per engine])."""
    start, count = bank["start"], bank["count"]
    hidden = weights["w2"].shape[1]
    local_set = list(range(start, start + count))
    ea = state["ea"]
    ok, lines = {}, []
    first = {e: True for e in EA_ENGINES}
    worst = {e: 0.0 for e in EA_ENGINES}
    gen = torch.Generator().manual_seed(20261026)
    for tokens in range(1, EA2_MAX_T + 1):
        engines = [e for e in _ea_engines(tokens) if e not in ea.get("skip", ())]
        ok[tokens] = {e: True for e in engines}
        for label, ids in _ea_routings(tokens, gen, local_set, device):
            if time.perf_counter() - t_prepare > EA_GATE_DEADLINE_S:
                ok[tokens] = {e: False for e in engines}
                lines.append(f"{EA_TAG} canary T={tokens} {label}: skipped: deadline")
                continue
            x = torch.randn((tokens, hidden), generator=gen).to(torch.bfloat16).to(device)
            tw = torch.rand((tokens, TOP_K), generator=gen)
            tw = (tw / tw.sum(-1, keepdim=True)).to(device)
            data = {"hidden_states": x, "topk_ids": ids, "topk_weights": tw, "config": _ea_cfg(bank, tokens, hidden)}
            master = kernel_fn(data, state).float()
            ref = _combo_ref_fp32(weights, bank, state, x, ids, tw)
            torch.cuda.synchronize()
            m_rel = _combo_rel(master, ref)
            n_act = len({int(e) for e in (ids.long() - start).flatten().tolist() if 0 <= e < count})
            for eng in engines:
                ea["err"].zero_()
                try:
                    if first[eng]:
                        print(f"{EA_TAG} first {eng} launch: T={tokens} {label} (each launch named, synced)", flush=True)
                    out = _ea_forward(x, ids, tw, bank, state,
                                      _rt_tracer(EA_TAG, f"{eng} T={tokens} {label}") if first[eng] else None, eng)
                    torch.cuda.synchronize()
                    first[eng] = False
                    errw = int(ea["err"][0])
                    good, rel, row, text = _rt_check(out, ref)
                    good = good and errw == 0 and rel <= 2.0 * max(m_rel, 2e-3)
                    if n_act == 0:
                        good = good and bool((out.float() == 0).all())
                    worst[eng] = max(worst[eng], rel)
                    msg = f"{text}, master {m_rel:.3g}, error word {errw}"
                except Exception as e:
                    good, msg = False, f"raised {type(e).__name__}: {str(e)[:200]}"
                ok[tokens][eng] = ok[tokens][eng] and good
                if not good:
                    lines.append(f"{EA_TAG} canary FAIL {eng} T={tokens} {label} (active {n_act}): {msg}")
                    print(lines[-1], flush=True)
    summary = []
    for eng, hi in EA_ENGINES.items():
        if eng in ea.get("skip", ()):
            summary.append(f"{EA_TAG} canary {eng}: skipped (occupancy below the other engines')")
            continue
        bad = [t for t in range(1, hi + 1) if not ok[t][eng]]
        summary.append(f"{EA_TAG} canary {eng}: T 1..{hi} " + (f"FAIL at T {bad}" if bad else "clean") +
                       f"; worst rel-L2 vs fp32 {worst[eng]:.3g}")
    return ok, lines, summary

def _ea_kernel_rates(weights, bank, state, device):
    """Kernel-only graph times (read flush, baseline subtracted) of each engine's w13 and w2 per class on judge-like
    zipf routings, with TB/s on the active experts' bytes. Lines only."""
    ea = state["ea"]
    ext = ea["ext"]
    start, count, inter = bank["start"], bank["count"], bank["size_n"]
    hidden = weights["w2"].shape[1]
    local_set = list(range(start, start + count))
    gen = torch.Generator().manual_seed(20261027)
    lines = []
    for tokens in EA_CLASSES:
        ids = _combo_routings(tokens, gen, local_set, device)["zipf"]
        n_act = len({int(e) for e in (ids.long() - start).flatten().tolist() if 0 <= e < count})
        x = torch.randn((tokens, hidden), generator=gen).to(torch.bfloat16).to(device)
        lid = torch.empty((tokens, TOP_K), dtype=torch.int32, device=device)
        y = torch.empty((tokens * TOP_K, hidden), dtype=torch.bfloat16, device=device)
        b13 = n_act * 2 * inter * (hidden // 2 + hidden // 16)
        b2 = n_act * hidden * (inter // 2 + inter // 16)
        for eng in _ea_engines(tokens):
            if eng in ea.get("skip", ()):
                continue
            if eng == "v1":
                h = torch.zeros((32, tokens, inter), dtype=torch.bfloat16, device=device)
                f13, f2 = ext.ea_w13, ext.ea_w2
            else:
                h = torch.zeros((tokens * TOP_K, inter), dtype=torch.bfloat16, device=device)
            # audit: each engine's own entry points and records (v4 / v5 used to fall through to v3's)
            k13, k2, r13, r2 = {"v1": ("ea_w13", "ea_w2", "w13r", "w2r"), "v2": ("ea2_w13", "ea2_w2", "w13r", "w2r"),
                                "v3": ("ea3_w13", "ea3_w2", "w13r", "w2r"), "v4": ("ea4_w13", "ea4_w2", "w13r", "w2r"),
                                "v4c": ("ea4_w13", "ea4_w2", "w13r", "w2r"),
                                "v5": ("ea5_w13", "ea5_w2", "w13r5", "w2r5")}[eng]
            pb = EA_PDL_BITS.get(eng, 0)
            f13, f2 = getattr(ext, k13), getattr(ext, k2)
            g13, _ = _rt_graph(lambda: f13(x, ids, ea[r13], ea["gs13"], h, lid, ea["ws13"], ea["tk13"], ea["err"],
                                           tokens, start, count, ea["grid"], ea["dq"], pb))
            g2, _ = _rt_graph(lambda: f2(h, ids, ea[r2], ea["gs2"], y, ea["ws2"], ea["tk2"], ea["err"], tokens,
                                         start, count, ea["grid"], ea["dq"], pb))
            r = _rt_time({"w13": g13, "w2": g2}, device, reps=21, rounds=1)
            t13, t2 = _rt_stats(r[0]["w13"])[0], _rt_stats(r[0]["w2"])[0]
            lines.append(f"{EA_TAG} kernel-only {eng} T={tokens} zipf active={n_act}: w13 {t13:.2f} us "
                         f"({b13 / max(t13, 1e-3) / 1e6:.2f} TB/s), w2 {t2:.2f} us "
                         f"({b2 / max(t2, 1e-3) / 1e6:.2f} TB/s), sum {t13 + t2:.2f} us for {(b13 + b2) / 1e6:.1f} MB")
            del g13, g2
    return lines

def _ea_gate(weights, bank, state, device, ok, t_prepare):
    """Per class: kernel_fn with each canary-clean engine vs master's routed path, cold-L2 graph replays on a judge-like
    zipf and a random routing, two interleaved rounds (_rt_select: every round >= 1.03x, or >= 1.02x with a tight IQR;
    the qualifying engine with the best worst ratio wins). Returns ({class: engine or None}, [lines])."""
    ea = state["ea"]
    start, count = bank["start"], bank["count"]
    hidden = weights["w2"].shape[1]
    local_set = list(range(start, start + count))
    gen = torch.Generator().manual_seed(20261028)
    won, lines = {}, []
    for cls in EA_CLASSES:
        won[cls] = None
        cands = [e for e in _ea_engines(cls) if ok.get(cls, {}).get(e, False)]
        if not cands:
            lines.append(f"{EA_TAG} gate T={cls}: no canary-clean engine, master kept")
            continue
        if time.perf_counter() - t_prepare > EA_GATE_DEADLINE_S:
            lines.append(f"{EA_TAG} gate T={cls}: skipped: deadline, master kept")
            continue
        per = {}
        for rlabel, ids in _combo_routings(cls, gen, local_set, device).items():
            tw = torch.rand((cls, TOP_K), generator=gen)
            data = {"hidden_states": torch.randn((cls, hidden), generator=gen).to(torch.bfloat16).to(device),
                    "topk_ids": ids, "topk_weights": (tw / tw.sum(-1, keepdim=True)).to(device),
                    "config": _ea_cfg(bank, cls, hidden)}
            graphs = {}
            for name in ["master"] + cands:
                ea["on"][cls] = False if name == "master" else name
                graphs[name], _ = _rt_graph(lambda: kernel_fn(data, state))
            ea["on"][cls] = False
            per[f"T={cls} {rlabel}"] = _rt_time(graphs, device)
            del graphs
        win, worst, glines = _rt_select(per, "master", cands, prefer_within=EA_PREFER_WITHIN)
        pin = EA_PIN.get(cls)
        if pin and pin in cands:
            win = pin
        lines.extend(f"{EA_TAG} gate {ln}" for ln in glines)
        won[cls] = win
        lines.append(f"{EA_TAG} gate T={cls}: worst ratio " + ", ".join(f"{c} {worst[c]:.3f}" for c in cands) +
                     f" -> {'ENGINE A ' + win if win else 'master'}" + (" PINNED" if pin and win == pin else ""))
    return won, lines

def _ea_cmb_gate(weights, bank, state, device):
    """Per ON class: kernel_fn with the class's engine and the Triton combine vs the CUDA combine (PDL-linked to K2) on
    a judge-like zipf and a random routing; the CUDA combine stays unless some round has it slower (ratio < 0.995).
    Sets state['ea']['cmb_t'][T] for every ON T of a class that keeps it. Returns [lines]."""
    ea = state["ea"]
    start, count = bank["start"], bank["count"]
    hidden = weights["w2"].shape[1]
    local_set = list(range(start, start + count))
    gen = torch.Generator().manual_seed(20261035)
    lines = []
    for cls in EA_CLASSES:
        if not ea["on"].get(cls, False):
            continue
        per = {}
        for rlabel, ids in _combo_routings(cls, gen, local_set, device).items():
            tw = torch.rand((cls, TOP_K), generator=gen)
            data = {"hidden_states": torch.randn((cls, hidden), generator=gen).to(torch.bfloat16).to(device),
                    "topk_ids": ids, "topk_weights": (tw / tw.sum(-1, keepdim=True)).to(device),
                    "config": _ea_cfg(bank, cls, hidden)}
            graphs = {}
            for name, flag in (("triton", 0), ("cuda", 1)):
                ea["cmb_t"][cls] = flag
                graphs[name], _ = _rt_graph(lambda: kernel_fn(data, state))
            ea["cmb_t"][cls] = 0
            per[f"T={cls} {rlabel}"] = _rt_time(graphs, device)
            del graphs
        win, worst, glines = _rt_select(per, "triton", ["cuda"], margin=0.995, tight=0.995)
        for ln in glines:
            print(f"{EA_TAG} combine gate {ln}", flush=True)
        keep = win == "cuda"
        for t in range(1, EA2_MAX_T + 1):
            if _ea_class(t) == cls and ea["on"][t]:
                ea["cmb_t"][t] = 1 if keep else 0
        lines.append(f"{EA_TAG} combine gate T={cls}: Triton/CUDA worst ratio {worst['cuda']:.3f} -> "
                     f"{'CUDA' if keep else 'Triton'}")
    for t, eng in EA_CMB_PIN.items():  # carrier: a prepare-time constant; _ea_cmb_verify and the copy check guard it
        if ea["on"].get(t) == eng:
            ea["cmb_t"][t] = 1
            lines.append(f"{EA_TAG} combine gate T={t}: CUDA PINNED ({eng})")
    return lines

def _ea_big(weights, bank, state, device, t_prepare):
    """Engine A at exactly T = 128 / 256 over EA_BIG_ENGINES: an eager, synced canary per engine on every routing kind
    (fp32 reference, half the judge's bounds, <= 2x master's error, error word 0, exact zeros without local routes; first
    launch traced), then kernel_fn master vs every canary-clean engine on three reference-style draws
    (_ea_judge_routings: p10 / p50 / p90 by v3 passes; _rt_select: the qualifying engine with the best worst ratio).
    Sets state['ea']['on'][T] to the winner. Returns [lines]."""
    ea = state["ea"]
    start, count = bank["start"], bank["count"]
    hidden = weights["w2"].shape[1]
    local_set = list(range(start, start + count))
    gen = torch.Generator().manual_seed(20261043)
    lines = []
    first = {e: True for e in EA_ENGINES}
    engines = [e for e in EA_BIG_ENGINES if e in EA_ENGINES and e not in ea.get("skip", ())]
    if not engines:
        return [f"{EA_TAG} big T {EA_BIG}: {'/'.join(EA_BIG_ENGINES)} skipped (occupancy or build)"]
    for tokens in EA_BIG:
        ea["on"][tokens] = False
        good = {e: True for e in engines}
        worst = {e: 0.0 for e in engines}
        m_worst = 0.0
        for label, ids in _ea_routings(tokens, gen, local_set, device):
            if time.perf_counter() - t_prepare > EA_GATE_DEADLINE_S:
                good = {e: False for e in engines}
                lines.append(f"{EA_TAG} big canary T={tokens} {label}: skipped: deadline")
                break
            x = torch.randn((tokens, hidden), generator=gen).to(torch.bfloat16).to(device)
            tw = torch.rand((tokens, TOP_K), generator=gen)
            tw = (tw / tw.sum(-1, keepdim=True)).to(device)
            data = {"hidden_states": x, "topk_ids": ids, "topk_weights": tw, "config": _ea_cfg(bank, tokens, hidden)}
            master = kernel_fn(data, state).float()
            ref = _combo_ref_fp32(weights, bank, state, x, ids, tw)
            torch.cuda.synchronize()
            m_rel = _combo_rel(master, ref)
            m_worst = max(m_worst, m_rel)
            n_act = len({int(e) for e in (ids.long() - start).flatten().tolist() if 0 <= e < count})
            for eng in engines:
                ea["err"].zero_()
                try:
                    if first[eng]:
                        print(f"{EA_TAG} first big {eng} launch: T={tokens} {label} (synced)", flush=True)
                    out = _ea_forward(x, ids, tw, bank, state,
                                      _rt_tracer(EA_TAG, f"{eng} T={tokens} {label}") if first[eng] else None, eng)
                    torch.cuda.synchronize()
                    first[eng] = False
                    errw = int(ea["err"][0])
                    ok_, rel, row, text = _rt_check(out, ref)
                    ok_ = ok_ and errw == 0 and rel <= 2.0 * max(m_rel, 2e-3)
                    if n_act == 0:
                        ok_ = ok_ and bool((out.float() == 0).all())
                    worst[eng] = max(worst[eng], rel)
                    msg = f"{text}, master {m_rel:.3g}, error word {errw}"
                except Exception as e:
                    ok_, msg = False, f"raised {type(e).__name__}: {str(e)[:200]}"
                if not ok_:
                    good[eng] = False
                    lines.append(f"{EA_TAG} big canary FAIL {eng} T={tokens} {label} (active {n_act}): {msg}")
                    print(lines[-1], flush=True)
        lines.append(f"{EA_TAG} big canary T={tokens}: " + ", ".join(
            f"{e} {'clean' if good[e] else 'FAIL'} (worst rel-L2 vs fp32 {worst[e]:.3g})" for e in engines)
            + f" (master {m_worst:.3g})")
        cands = [e for e in engines if good[e]]
        if not cands or time.perf_counter() - t_prepare > EA_GATE_DEADLINE_S:
            continue
        per = {}
        for rlabel, ids in _ea_judge_routings(tokens, gen, start, count, device).items():
            tw = torch.rand((tokens, TOP_K), generator=gen)
            data = {"hidden_states": torch.randn((tokens, hidden), generator=gen).to(torch.bfloat16).to(device),
                    "topk_ids": ids, "topk_weights": (tw / tw.sum(-1, keepdim=True)).to(device),
                    "config": _ea_cfg(bank, tokens, hidden)}
            graphs = {}
            for name in ["master"] + cands:
                ea["on"][tokens] = False if name == "master" else name
                graphs[name], _ = _rt_graph(lambda: kernel_fn(data, state))
            ea["on"][tokens] = False
            per[f"T={tokens} {rlabel}"] = _rt_time(graphs, device)
            del graphs
        win, wr, glines = _rt_select(per, "master", cands, prefer_within=EA_PREFER_WITHIN)
        for ln in glines:
            print(f"{EA_TAG} big gate {ln}", flush=True)
        ea["on"][tokens] = win if win else False
        lines.append(f"{EA_TAG} big gate T={tokens}: worst ratio " + ", ".join(f"{c} {wr[c]:.3f}" for c in cands)
                     + f" -> {'ENGINE A ' + win if win else 'master'}")
    return lines

def _ea_g2_gate(weights, bank, state, device):
    """T=1 class: kernel_fn with K2 on one CTA per SM (grid = SMs: the aligned split then gives each CTA a whole w2 group,
    no fix-up, 8 chunks to amortise its start) vs the full grid, on a judge-like zipf and a random routing; the smaller
    grid must win every round by >= 1.02 (_rt_select). Sets state['ea']['g2_t'][1]. Returns [lines]."""
    ea = state["ea"]
    start, count = bank["start"], bank["count"]
    hidden = weights["w2"].shape[1]
    local_set = list(range(start, start + count))
    gen = torch.Generator().manual_seed(20261041)
    lines = []
    cls = 1
    if not ea["on"].get(cls, False):
        return lines
    half = ea["grid"] // EA_CTAS_PER_SM
    per = {}
    for rlabel, ids in _combo_routings(cls, gen, local_set, device).items():
        tw = torch.rand((cls, TOP_K), generator=gen)
        data = {"hidden_states": torch.randn((cls, hidden), generator=gen).to(torch.bfloat16).to(device),
                "topk_ids": ids, "topk_weights": (tw / tw.sum(-1, keepdim=True)).to(device),
                "config": _ea_cfg(bank, cls, hidden)}
        graphs = {}
        for name, g in (("full", ea["grid"]), ("one_per_sm", half)):
            ea["g2_t"][cls] = g
            graphs[name], _ = _rt_graph(lambda: kernel_fn(data, state))
        ea["g2_t"].pop(cls, None)
        per[f"T={cls} {rlabel}"] = _rt_time(graphs, device)
        del graphs
    win, worst, glines = _rt_select(per, "full", ["one_per_sm"], margin=1.02, tight=1.02)
    for ln in glines:
        print(f"{EA_TAG} k2 grid gate {ln}", flush=True)
    if win == "one_per_sm":
        ea["g2_t"][cls] = half
    lines.append(f"{EA_TAG} k2 grid gate T=1 ({ea['on'][cls]}): full/{half}-CTA worst ratio {worst['one_per_sm']:.3f} -> "
                 f"{'K2 grid ' + str(half) if win else 'full grid'}")
    return lines

def _ea_cmb_verify(weights, bank, state, device):
    """Each class that kept the CUDA combine, end to end against the fp32 reference (_rt_check at half the judge's
    bounds, like the canary) on a judge-like zipf routing; a miss turns that class back to the Triton combine.
    Returns [lines]."""
    ea = state["ea"]
    start, count = bank["start"], bank["count"]
    hidden = weights["w2"].shape[1]
    local_set = list(range(start, start + count))
    gen = torch.Generator().manual_seed(20261038)
    lines = []
    for cls in (*EA_CLASSES, *EA_CMB_PIN):
        if not (ea["on"].get(cls, False) and ea["cmb_t"].get(cls, 0)):
            continue
        ids = _combo_routings(cls, gen, local_set, device)["zipf"]
        x = torch.randn((cls, hidden), generator=gen).to(torch.bfloat16).to(device)
        tw = torch.rand((cls, TOP_K), generator=gen)
        tw = (tw / tw.sum(-1, keepdim=True)).to(device)
        out = _ea_forward(x, ids, tw, bank, state)
        ref = _combo_ref_fp32(weights, bank, state, x, ids, tw)
        torch.cuda.synchronize()
        good, rel, row, text = _rt_check(out, ref)
        if not good:
            for t in range(1, EA2_MAX_T + 1):
                if _ea_class(t) == cls:
                    ea["cmb_t"][t] = 0
            ea["cmb_t"][cls] = 0  # a pinned big T (EA_CMB_PIN)
        lines.append(f"{EA_TAG} combine verify T={cls} ({ea['on'][cls]} + CUDA combine): {text} -> "
                     f"{'ok' if good else 'FAIL -> Triton combine'}")
    return lines

def _ea_copy_check(weights, bank, state, device):
    """The judge copies the prepared state (cloned tensors) and rotates the copies: graphs of kernel_fn on this state
    and on a tensor-cloning copy, alternating replays with refilled inputs, each against eager kernel_fn on this
    state, at the smallest and largest ON T and the smallest T of each ON engine. A miss turns every T back to master.
    Returns a line."""
    ea = state["ea"]
    start, count = bank["start"], bank["count"]
    hidden = weights["w2"].shape[1]
    local_set = list(range(start, start + count))
    ts = sorted(t for t, v in ea["on"].items() if v)
    if not ts:
        return f"{EA_TAG} copy check: no T is ON"
    picks = sorted({ts[0], ts[-1]} | {min(t for t in ts if ea["on"][t] == e) for e in {ea["on"][t] for t in ts}}
                   | {t for t in EA_CMB_PIN if ea["on"].get(t) and ea["cmb_t"].get(t)})
    other = _wg_copy_tree(state)
    gen = torch.Generator().manual_seed(20261029)
    fails, n = [], 0
    for tokens in picks:
        cfg = _ea_cfg(bank, tokens, hidden)
        per = []
        for st in (state, other):
            data = {"hidden_states": torch.zeros((tokens, hidden), dtype=torch.bfloat16, device=device),
                    "topk_ids": torch.full((tokens, TOP_K), start, dtype=torch.int32, device=device),
                    "topk_weights": torch.full((tokens, TOP_K), 1.0 / TOP_K, dtype=torch.float32, device=device),
                    "config": cfg}
            graph, out = _rt_graph(lambda data=data, st=st: kernel_fn(data, st))
            per.append((data, graph, out))
        routs = dict(_ea_routings(tokens, gen, local_set, device))
        for k in range(4):
            ids = routs["zipf" if k % 2 == 0 else "skewed-4hot"]
            x = torch.randn((tokens, hidden), generator=gen).to(torch.bfloat16).to(device)
            tw = torch.rand((tokens, TOP_K), generator=gen).to(device)
            for data, _, _ in per:
                data["hidden_states"].copy_(x)
                data["topk_ids"].copy_(ids)
                data["topk_weights"].copy_(tw)
            for _, graph, _ in (per if k % 2 == 0 else per[::-1]):
                graph.replay()
            torch.cuda.synchronize()
            ref = kernel_fn({"hidden_states": x, "topk_ids": ids, "topk_weights": tw, "config": cfg}, state).float()
            for i, (_, _, out) in enumerate(per):
                n += 1
                rel = _combo_rel(out.float(), ref)
                if not rel <= EA_COPY_TOL:
                    fails.append(f"T={tokens} ({ea['on'][tokens]}) state {'AB'[i]} refill {k}: rel-L2 vs eager {rel:.3g}")
        del per
        torch.cuda.synchronize()
    if fails:
        for t in ts:
            ea["on"][t] = False
    del other
    gc.collect()
    torch.cuda.empty_cache()
    return f"{EA_TAG} copy check: {n} replays on two states, T {picks}: " + \
        ("PASS" if not fails else f"FAIL -> master for every T: {fails[0]}")

def _ea_setup(weights, state, device, t_prepare):
    """Untimed, after master's prepare. Never raises: any miss leaves state['ea']['on'][T] False (master's path).
    Detail lines print once as they happen; the return value is the compact summary for prepare() to print last."""
    lines = []

    def say(s):
        lines.append(s)
        print(s, flush=True)

    state["ea"] = {"on": {t: False for t in (*range(1, EA2_MAX_T + 1), *EA_BIG)}, "max_t": EA2_MAX_T, "cmb_t": {},
                   "g2_t": {}}
    t0 = time.perf_counter()
    try:
        bank = state["banks"][(0, 32)]
        if time.perf_counter() - t_prepare > EA_START_DEADLINE_S:
            raise RuntimeError(f"skipped: deadline (start at {time.perf_counter() - t_prepare:.1f} s)")
        inter, count = bank["size_n"], bank["count"]
        hidden = weights["w2"].shape[1]
        if (inter != 4096 or hidden != 4096 or count > 32 or bank["expert_map"] is None
                or tuple(torch.cuda.get_device_capability(device)) < (9, 0)):
            raise RuntimeError(f"unsupported: I={inter} H={hidden} count={count}")
        ext, err_text, dt, occs, ilines = _ea2_build_ext(EA_TAG, EA_EXT_NAME, t_prepare, EA_START_DEADLINE_S)
        if ext is None:
            raise RuntimeError(f"build failed: {err_text[-400:]}")
        for ln in ilines:
            say(ln)
        dq = 2 if _ea_scales_ok(weights, bank["start"], count) else 1
        # CTAs/SM from v1 / v2; v3 (D = 3, 16 x rows) runs only if it reaches the same occupancy
        cps = max(1, min([EA_CTAS_PER_SM] + [v for k, v in occs.items() if k.endswith(f"dq{dq}") and k[:2] in ("v1", "v2")]))
        # an engine without occupancy entries (v4 when only the fallback module built) is skipped too
        state["ea"]["skip"] = {e for e in EA_ENGINES if e not in ("v1", "v2")
                               and min((v for k, v in occs.items() if k.startswith(e + " ") and k.endswith(f"dq{dq}")),
                                       default=0) < cps}
        sms = int(torch.cuda.get_device_properties(device).multi_processor_count)
        t1 = time.perf_counter()
        state["ea"].update(_ea_repack(weights, bank["start"], count, dq))
        torch.cuda.synchronize()
        grid = cps * sms
        state["ea"].update({"ext": ext, "dq": dq, "grid": grid, "pdl": 1, **_ea2_buffers(device, grid, inter)})
        if "v5" in EA_ENGINES and "v5" not in state["ea"]["skip"]:
            try:  # v5's 256-k records (a permutation of v3's); a miss skips v5
                state["ea"].update(_ea5_repack(state["ea"], count))
            except Exception as e:
                state["ea"]["skip"].add("v5")
                say(f"{EA_TAG} v5 repack failed, v5 skipped: {type(e).__name__}: {str(e)[:200]}")
        say(f"{EA_TAG} {EA_LAYOUT_NAME[dq]}; repack {time.perf_counter() - t1:.1f} s; grid {grid} "
            f"({cps} CTAs/SM; v1..v3 160 threads, v4 / v5 288); build {dt:.1f} s")
        ok, flines, slines = _ea_canary(weights, bank, state, device, t_prepare)
        lines.extend(flines)  # printed by the canary as they happened
        for ln in slines:
            say(ln)
        if not any(v for d in ok.values() for v in d.values()):
            raise RuntimeError("canary failed for every T and engine")
        if time.perf_counter() - t_prepare < EA_GATE_DEADLINE_S and not CAMPAIGN_LEAN_DIAG:  # off: lean diagnostics
            try:  # diagnostic only: a miss here must not turn Engine A off
                lines.extend(_ea_kernel_rates(weights, bank, state, device))
            except Exception as e:
                lines.append(f"{EA_TAG} kernel-only rates raised {type(e).__name__}: {str(e)[:200]}")
        won, glines = _ea_gate(weights, bank, state, device, ok, t_prepare)
        for ln in glines:
            if "round" in ln:
                say(ln)
            else:
                lines.append(ln)
        for t in range(1, EA2_MAX_T + 1):
            w = won.get(_ea_class(t))
            state["ea"]["on"][t] = w if (w is not None and ok[t].get(w, False)) else False
        if time.perf_counter() - t_prepare < EA_GATE_DEADLINE_S:
            try:  # a miss leaves T = 128 / 256 on master
                lines.extend(_ea_big(weights, bank, state, device, t_prepare))
            except Exception as e:
                for t in EA_BIG:
                    state["ea"]["on"][t] = False
                lines.append(f"{EA_TAG} big classes raised {type(e).__name__}: {str(e)[:200]}")
        if any(state["ea"]["on"].values()) and time.perf_counter() - t_prepare < EA_GATE_DEADLINE_S:
            try:  # a miss leaves K2 on the full grid
                lines.extend(_ea_g2_gate(weights, bank, state, device))
            except Exception as e:
                state["ea"]["g2_t"] = {}
                lines.append(f"{EA_TAG} k2 grid gate raised {type(e).__name__}: {str(e)[:200]}")
        if any(state["ea"]["on"].values()) and time.perf_counter() - t_prepare < EA_GATE_DEADLINE_S:
            try:  # a miss leaves the Triton combine everywhere
                cok, cline = _ea_cmb_check(ext, state["post_norm_w"], device)
                state["ea"]["cmb_ok"] = bool(cok)  # S3: Engine A v6 uses the CUDA combine whenever it checked out
                lines.append(f"{EA_TAG} {cline}")
                if cok:
                    lines.extend(_ea_cmb_gate(weights, bank, state, device))
                    lines.extend(_ea_cmb_verify(weights, bank, state, device))
            except Exception as e:
                state["ea"]["cmb_t"] = {}
                lines.append(f"{EA_TAG} combine check raised {type(e).__name__}: {str(e)[:200]}")
        if CAMPAIGN_EA6:  # S3: Engine A v6 (ea6_core.py) raced against T = 1 / T = 8's incumbents; never raises
            lines.extend(_ea6_stage(weights, bank, state, device, t_prepare))
        _ea5_drop_unused(state["ea"])
        if any(state["ea"]["on"].values()):
            if time.perf_counter() - t_prepare > EA_COPY_DEADLINE_S:
                for t in state["ea"]["on"]:
                    state["ea"]["on"][t] = False
                lines.append(f"{EA_TAG} copy check: skipped: deadline -> master for every T")
            else:
                lines.append(_ea_copy_check(weights, bank, state, device))
            state["ea"]["copy_line"] = lines[-1]  # S3: printed again among prepare()'s last lines
    except Exception as e:  # prepare only: never raises, every T stays on master
        for t in state["ea"]["on"]:
            state["ea"]["on"][t] = False
        lines.append(f"{EA_TAG} {type(e).__name__}: {str(e)[:400]}")
    try:
        torch.cuda.synchronize()
    except Exception as e:
        lines.append(f"{EA_TAG} final sync raised {type(e).__name__}: {str(e)[:200]}")
    tail = [f"{EA_TAG} ===== ENGINE A SUMMARY ({time.perf_counter() - t0:.1f} s; module {EA_EXT_NAME}) ====="]
    tail.extend(ln for ln in lines if "kernel-only" in ln or ("gate T=" in ln and "round" not in ln)
                or "copy check" in ln or f"{EA_TAG} canary v" in ln or "repack" in ln or "Error" in ln
                or "skipped" in ln or (("combine" in ln or "grid gate" in ln or "big " in ln) and "round" not in ln
                                         and "FAIL v" not in ln))
    tail.extend(_ea_moe_path_lines(state["ea"]))
    return tail

def _ea_moe_path_lines(ea):
    """Engine A's PATH CHOSEN lines (T 1..EA2_MAX_T runs, then EA_BIG), each marked PINNED where a pin decided it."""
    on, out = ea["on"], []
    for ln in _ea_path_lines(EA_TAG, on, EA2_MAX_T):
        a, _, b = ln.split("PATH CHOSEN T=", 1)[1].split(" ", 1)[0].partition("..")
        cls = sorted({_ea_class(t) for t in range(int(a), int(b or a) + 1)
                      if on[t] and EA_PIN.get(_ea_class(t)) == on[t]})
        out.append(ln + (f" PINNED (class {'/'.join(map(str, cls))})" if cls else ""))
    for t in EA_BIG:
        pin = bool(on.get(t)) and EA_CMB_PIN.get(t) == on[t] and bool(ea.get("cmb_t", {}).get(t))
        out.append(f"{EA_TAG} PATH CHOSEN T={t} = {'ENGINE A ' + on[t] if on.get(t) else 'MASTER'}" +
                   (" + CUDA combine PINNED" if pin else ""))
    return out
# ---- end include rewrite/lib/ea_moe.py ----
# ---- begin include rewrite/lib/ea6_core.py ----
# Engine A v6 (expert-bandwidth S3; research/s3-panel-2026-10-28.md section 6), moe only: whole 16-row records per
# CTA, one 320-thread CTA per SM (ea6_kernels.cuh); "v6s" = K2 launched without PDL. Not in EA_ENGINES: _ea6_stage (from
# _ea_setup) has its own canary, race, anatomy and copy check. v1's repack and state dict. Include after ea_moe.py.
EA6_TAG = "[ea6]"
EA6_JOIN_S = 170.0                 # the build thread is joined by this many s into prepare()
EA6_START_S = 170.0                # the stage starts only before this
EA6_GATE_S = 200.0                 # canary, kernel-only, races and anatomy start only before this
EA6_COPY_S = 215.0                 # v6's own copy check starts only before this: the stage leaves >= ~45 s for the
                                   # shared copy check (EA_COPY_DEADLINE_S 262) and the hybrid (HM_START 250)
EA6_CLASSES = (1, 8)               # T = 1 alone; T = 2..8 follow T = 8
EA6_W1 = {2: 0.475, 3: 0.43, 4: 0.085, 5: 0.01}   # the judge's T = 1 mix by distinct local experts (8f33e5ee)
EA6_FLOOR = {1: 0.95, 2: 0.97, 3: 0.97, 4: 0.97, 5: 0.95}   # per-n floor on incumbent / arm, every round
EA6_FLOOR8 = 0.97                  # per-draw floor at T = 8
EA6_ANATOMY = True                 # per-CTA phases from the debug buffer (diagnostic only, never routes)
EA6_SEED = 20261060
EA6_DBG = 8                        # eak6::DBG int64 per CTA
EA6_LINES = []                     # prepare()-only, printed last (each <= 199 chars)
_EA6_BUILD = {}

_EA6_CPP = r"""
#include <torch/extension.h>
#include <vector>
std::vector<int64_t> ea6_info();
void ea6_w13(torch::Tensor x, torch::Tensor topk_ids, torch::Tensor wr, torch::Tensor gs, torch::Tensor h,
             torch::Tensor local_ids, torch::Tensor err, torch::Tensor dbg, int64_t T, int64_t start, int64_t count,
             int64_t grid, int64_t minb, int64_t flags);
void ea6_w2(torch::Tensor h, torch::Tensor topk_ids, torch::Tensor wr, torch::Tensor gs, torch::Tensor y,
            torch::Tensor err, torch::Tensor dbg, int64_t T, int64_t start, int64_t count, int64_t grid, int64_t minb,
            int64_t flags);
"""
_EA6_SRC_BODY = r"""
// ---- begin include rewrite/lib/cuda/ea6_kernels.cuh ----
// Engine A v6 (expert-bandwidth S3; research/s3-panel-2026-10-28.md section 6), T <= 8, dq2 only. K1 / K2 compute what
// v1's do. A CTA (320 threads, one per SM) owns whole RECORDS (a 16-row warp record of v1's repack over the full K: 8
// pieces of 4608 B): warp w consumes chunk w against the resident B, warp 8 streams a D-record ring, warp 9 sums the 8
// partials in warp order and writes h / y. No split-K, tickets or workspace; no CTA waits on another. Needs ea_common.cuh
// and ea_kernels.cuh's namespace eak.
namespace eak6 {
using namespace ea;

constexpr int THREADS = 320;               // warps 0..7 consume, warp 8 produces, warp 9 runs the epilogue
constexpr int RECB = eak::NK * eak::REC;   // 36,864 B: one record (8 pieces of 4608 B)
constexpr int PBYTES = 2 * 8 * 32 * 16;    // P: 2 buffers x 8 warps x 32 lanes x float4
constexpr int D13 = 3;                     // ring depth in records, K1
constexpr int D2 = 2;                      // ring depth in records, K2
constexpr int K2_PAD = 118784;             // K2's request when co-residency with K1 is not intended (one K2 CTA per SM)
constexpr int DBG = 8;                     // int64 per CTA in the prepare-only debug buffer

// Dynamic smem: ring D x 36,864 | B 8 T x 1040 | P 8192 | mbarriers full[D] empty[D] bfull pfull[2] pfree[2] | s_n,
// s_act[32] (136 B). K1 (D 3): 127,328 B at T = 1, 185,568 at T = 8; K2 (D 2): 90,448 / 148,688.
__host__ __device__ constexpr int smem6(int D, int T) {
  return D * RECB + 8 * eak::XROW * T + PBYTES + 8 * (2 * D + 5) + 136;
}

__device__ __forceinline__ long long gtimer() {
  long long t;
  asm volatile("mov.u64 %0, %%globaltimer;\n" : "=l"(t));
  return t;
}

// flags: 1 = K2 has the PDL attribute (host), 2 = K2 may sit beside K1 (host: unpadded request at T = 1 with 1),
// 4 = K1 waits first (decode). dbg (prepare only): per CTA 8 int64 at
// ((W13 ? 0 : 1) * G + c) * 8: entry, first record full, last consume, last epilogue, r, K2 wait returned, first
// epilogue, n (times %globaltimer ns).
template <bool W13, int D, int MINB>
__global__ void __launch_bounds__(THREADS, MINB)
ea6_kernel(const __nv_bfloat16* __restrict__ bsrc, const int* __restrict__ topk_ids, const uint8_t* __restrict__ wr,
           const float* __restrict__ gs, __nv_bfloat16* __restrict__ out, int* __restrict__ local_ids, int* err,
           long long* __restrict__ dbg, int T, int start, int count, int flags) {
  constexpr int NG = W13 ? 128 : 64;   // 64-row groups per expert
  constexpr int NREC = NG * 4;         // records per expert: 512 (w13) / 256 (w2)
  extern __shared__ __align__(128) uint8_t smem[];
  uint8_t* ring = smem;
  uint8_t* bsm = smem + D * RECB;
  float4* P = reinterpret_cast<float4*>(bsm + 8 * eak::XROW * T);
  uint64_t* bars = reinterpret_cast<uint64_t*>(smem + D * RECB + 8 * eak::XROW * T + PBYTES);
  int* s_n = reinterpret_cast<int*>(bars + 2 * D + 5);
  int* s_act = s_n + 1;
  const int warp = threadIdx.x >> 5, lane = threadIdx.x & 31;
  const uint32_t full0 = smem_u32(bars), empty0 = full0 + 8 * D, bfull = empty0 + 8 * D;
  const uint32_t pfull0 = bfull + 8, pfree0 = pfull0 + 16;
  const int G = static_cast<int>(gridDim.x), c = static_cast<int>(blockIdx.x);
  long long* dme = dbg != nullptr ? dbg + (static_cast<size_t>(W13 ? 0 : 1) * G + c) * DBG : nullptr;
  if (dme != nullptr && threadIdx.x == 0) dme[0] = gtimer();
  if (W13 && (flags & 4)) griddep_wait();  // decode: topk_ids / x come from the previous kernel
  if (warp == 0) eak::build_map(topk_ids, T, start, count, lane, s_act, s_n, local_ids, W13 && c == 0);
  if (threadIdx.x == 32) {
#pragma unroll
    for (int d = 0; d < D; ++d) {
      mbar_init(full0 + 8 * d, 1);
      mbar_init(empty0 + 8 * d, 8);
    }
    mbar_init(bfull, 1);
#pragma unroll
    for (int k = 0; k < 2; ++k) {
      mbar_init(pfull0 + 8 * k, 8);
      mbar_init(pfree0 + 8 * k, 1);
    }
    fence_barrier_init();
  }
  __syncthreads();
  const int n = *s_n;
  // ---- this CTA's records [b, e): K1 flat q = a * 512 + rt over the active experts; K2 rt within expert a ----
  int a = 0, b = 0, e = 0;
  if (W13) {
    const long long R = static_cast<long long>(NREC) * n;
    b = static_cast<int>((static_cast<long long>(c) * R) / G);
    e = static_cast<int>((static_cast<long long>(c + 1) * R) / G);
  } else if (n > 0) {
    a = (c * n) / G;
    const int c0 = (G * a + n - 1) / n, c1 = (G * (a + 1) + n - 1) / n;
    const int m = c1 - c0, j = c - c0;
    b = (NREC * j) / m;
    e = (NREC * (j + 1)) / m;
  }
  const int r = e - b;
  if (dme != nullptr && threadIdx.x == 0) {
    dme[4] = r;
    dme[7] = n;
  }
  if (r <= 0) {  // CTA-uniform: no local route, or no record for this CTA
    if (!W13) griddep_wait();  // K2 must not complete before K1: the combine reads K1's local_ids
    griddep_launch();
    return;
  }
  // piece 0 of record q (pieces kc at + kc * STAGE_W): wr + ((le * NG + gi) * 8 + kc) * 18432 + wq * 4608
  auto rec_src = [&](int q) -> const uint8_t* {
    const int aa = W13 ? (q / NREC) : a;
    const int rt = W13 ? (q - aa * NREC) : q;
    const int le = s_act[aa];
    return wr + static_cast<size_t>(le * NG + (rt >> 2)) * eak::NK * eak::STAGE_W + (rt & 3) * eak::REC;
  };
  if (warp == 8) {
    // ---- producer ----
    bool dead = false;
    auto issue = [&](int i) {
      const int slot = i % D;
      const uint32_t fb = full0 + 8 * slot;
      if (lane == 0) mbar_expect_tx(fb, static_cast<uint32_t>(RECB));
      __syncwarp();
      if (lane < eak::NK)
        bulk_g2s(smem_u32(ring + slot * RECB + lane * eak::REC), rec_src(b + i) + static_cast<size_t>(lane) * eak::STAGE_W,
                 static_cast<uint32_t>(eak::REC), fb);
    };
    // B: chunk kc of token t (1024 B) from src + t * 4096 + kc * 512 to B + (kc * T + t) * 1040, all on bfull
    auto b_copy = [&](const __nv_bfloat16* src) {
      if (lane == 0) mbar_expect_tx(bfull, static_cast<uint32_t>(8 * T * 1024));
      __syncwarp();
      for (int k = lane; k < 8 * T; k += 32) {
        const int kc = k / T, t = k - kc * T;
        bulk_g2s(smem_u32(bsm + k * eak::XROW), src + static_cast<size_t>(t) * eak::KDIM + kc * 512, 1024u, bfull);
      }
    };
    const int pre = r < D ? r : D;
    if (W13) {
      b_copy(bsrc);
      for (int i = 0; i < pre; ++i) issue(i);
      mbar_wait(full0, 0u, err, dead);  // the first record landed: let K2 be scheduled
      griddep_launch();
    } else {
      for (int i = 0; i < pre; ++i) issue(i);  // weights do not depend on K1
      griddep_wait();
      if (dme != nullptr && lane == 0) dme[5] = gtimer();
      griddep_launch();
      b_copy(bsrc + static_cast<size_t>(a) * T * eak::KDIM);  // h of this CTA's expert, after K1 completed
    }
    for (int i = pre; i < r; ++i) {
      const int slot = i % D;
      mbar_wait(empty0 + 8 * slot, static_cast<uint32_t>(((i / D) - 1) & 1), err, dead);
      issue(i);
    }
    return;
  }
  if (warp < 8) {
    // ---- consumers: warp w takes chunk w of every record ----
    bool dead = false;
    if (!W13) {  // park while a co-resident K1 runs
      griddep_wait();
      griddep_launch();
    }
    mbar_wait(bfull, 0u, err, dead);
    const uint32_t xs = smem_u32(bsm) + static_cast<uint32_t>(warp * T * eak::XROW);
    for (int i = 0; i < r; ++i) {
      const int slot = i % D;
      mbar_wait(full0 + 8 * slot, static_cast<uint32_t>((i / D) & 1), err, dead);
      if (W13 && i == 0) griddep_launch();
      if (dme != nullptr && i == 0 && threadIdx.x == 0) dme[1] = gtimer();
      float acc[2][4] = {};
      eak::consume<2>(ring + slot * RECB + warp * eak::REC, xs, lane, T, acc);
      __syncwarp();
      if (lane == 0) mbar_arrive(empty0 + 8 * slot);
      const float4 cv = make_float4(acc[0][0] + acc[1][0], acc[0][1] + acc[1][1], acc[0][2] + acc[1][2],
                                    acc[0][3] + acc[1][3]);
      if (i >= 2) mbar_wait(pfree0 + 8 * (i & 1), static_cast<uint32_t>(((i >> 1) - 1) & 1), err, dead);
      P[((i & 1) * 8 + warp) * 32 + lane] = cv;
      __syncwarp();
      if (lane == 0) mbar_arrive(pfull0 + 8 * (i & 1));
    }
    if (dme != nullptr && threadIdx.x == 0) dme[2] = gtimer();
    return;
  }
  // ---- epilogue (warp 9): rows (g, g + 8) of each record, tokens 2 cq, 2 cq + 1 ----
  bool dead = false;
  if (!W13) {
    griddep_wait();
    griddep_launch();
  }
  const int g = lane >> 2, cq = lane & 3;
  // K2 serves one expert per CTA: the slots of tokens 2 cq + j that route to it are fixed for the CTA
  int le2 = 0;
  float sc2 = 0.f;
  uint32_t smask[2] = {0u, 0u};
  if (!W13) {
    le2 = s_act[a];
    sc2 = gs[le2];
#pragma unroll
    for (int j = 0; j < 2; ++j) {
      const int t = 2 * cq + j;
      if (t < T)
#pragma unroll
        for (int s = 0; s < 8; ++s)
          if (topk_ids[t * 8 + s] - start == le2) smask[j] |= 1u << s;
    }
  }
  for (int i = 0; i < r; ++i) {
    const int k = i & 1;
    mbar_wait(pfull0 + 8 * k, static_cast<uint32_t>((i >> 1) & 1), err, dead);
    if (W13 && i == 0) griddep_launch();
    const float4* pp = P + k * 256 + lane;
    float4 s = pp[0];
#pragma unroll
    for (int w = 1; w < 8; ++w) {  // ((p0 + p1) + p2) ... + p7, component-wise
      const float4 v = pp[w * 32];
      s.x += v.x;
      s.y += v.y;
      s.z += v.z;
      s.w += v.w;
    }
    __syncwarp();
    if (lane == 0) mbar_arrive(pfree0 + 8 * k);
    const float sv[4] = {s.x, s.y, s.z, s.w};
    const int q = b + i;
    if (W13) {
      const int aa = q / NREC, rt = q - aa * NREC;
      const int le = s_act[aa];
      const float sc = gs[le];  // global scale x 2^7 (the dequant bias)
      const int col = (rt >> 2) * 32 + (rt & 3) * 8 + g;  // rows g = gate col, g + 8 = up col
#pragma unroll
      for (int j = 0; j < 2; ++j) {
        const int t = 2 * cq + j;
        if (t < T)
          out[(static_cast<size_t>(aa) * T + t) * eak::KDIM + col] =
              __float2bfloat16_rn(eak::silu_mul(sv[j] * sc, sv[2 + j] * sc));
      }
    } else {
      const int n0 = (q >> 2) * 64 + (q & 3) * 16 + g;
#pragma unroll
      for (int j = 0; j < 2; ++j) {
        const int t = 2 * cq + j;
        if (t < T) {
          const __nv_bfloat16 v0 = __float2bfloat16_rn(sv[j] * sc2);
          const __nv_bfloat16 v1 = __float2bfloat16_rn(sv[2 + j] * sc2);
#pragma unroll
          for (int s2 = 0; s2 < 8; ++s2) {
            if ((smask[j] >> s2) & 1u) {
              __nv_bfloat16* yr = out + static_cast<size_t>(t * 8 + s2) * eak::KDIM;
              yr[n0] = v0;
              yr[n0 + 8] = v1;
            }
          }
        }
      }
    }
    if (dme != nullptr && i == 0 && lane == 0) dme[6] = gtimer();
  }
  if (dme != nullptr && lane == 0) dme[3] = gtimer();
}

}  // namespace eak6

// ---- host ----------------------------------------------------------------------------------------------------------
static int ea6_req(bool w13, int64_t T, int64_t flags) {
  if (w13) return eak6::smem6(eak6::D13, static_cast<int>(T));
  const int s = eak6::smem6(eak6::D2, static_cast<int>(T));
  // K2 meant to land beside K1 (219,824 B with both reserves <= 233,472): only when the host found the registers fit
  if (T == 1 && (flags & 1) && (flags & 2)) return s;
  return s > eak6::K2_PAD ? s : eak6::K2_PAD;  // never two K2 CTAs on one SM (the per-expert split assumes one)
}

template <typename F>
static void ea6_one_info(std::vector<int64_t>& r, F fn, bool w13) {
  const void* p = reinterpret_cast<const void*>(fn);
  const int smax = w13 ? eak6::smem6(eak6::D13, 8) : eak6::smem6(eak6::D2, 8);
  const int req1 = ea6_req(w13, 1, 3);
  const cudaError_t e1 = cudaFuncSetAttribute(p, cudaFuncAttributeMaxDynamicSharedMemorySize, smax);
  const cudaError_t e2 = cudaFuncSetAttribute(p, cudaFuncAttributePreferredSharedMemoryCarveout,
                                              cudaSharedmemCarveoutMaxShared);
  cudaFuncAttributes at{};
  const cudaError_t e3 = cudaFuncGetAttributes(&at, p);
  int occ = 0;
  const cudaError_t e4 = cudaOccupancyMaxActiveBlocksPerMultiprocessor(&occ, p, eak6::THREADS, req1);
  const bool ok = e1 == cudaSuccess && e2 == cudaSuccess && e3 == cudaSuccess && e4 == cudaSuccess;
  if (!ok) (void)cudaGetLastError();
  r.push_back(ok ? 1 : 0);
  r.push_back(at.numRegs);
  r.push_back(static_cast<int64_t>(at.localSizeBytes));
  r.push_back(w13 ? eak6::smem6(eak6::D13, 1) : eak6::smem6(eak6::D2, 1));
  r.push_back(smax);
  r.push_back(occ);
}

// Per instance (K1 m2, K1 m1, K2 m2, K2 m1): ok, regs, local bytes, smem T=1, smem T=8, CTAs/SM at the T=1 request.
// Also sets the smem limit and carveout: call before any launch.
std::vector<int64_t> ea6_info() {
  std::vector<int64_t> r;
  ea6_one_info(r, eak6::ea6_kernel<true, eak6::D13, 2>, true);
  ea6_one_info(r, eak6::ea6_kernel<true, eak6::D13, 1>, true);
  ea6_one_info(r, eak6::ea6_kernel<false, eak6::D2, 2>, false);
  ea6_one_info(r, eak6::ea6_kernel<false, eak6::D2, 1>, false);
  return r;
}

static void ea6_check(const torch::Tensor& topk_ids, const torch::Tensor& wr, const torch::Tensor& gs,
                      const torch::Tensor& err, const torch::Tensor& dbg, int64_t T, int64_t count, int64_t grid,
                      int64_t minb, int64_t ng, const char* what) {
  TORCH_CHECK(T >= 1 && T <= 8 && count >= 1 && count <= 32 && grid >= 32 && grid <= 1024 && (minb == 1 || minb == 2),
              what, ": arguments");
  TORCH_CHECK(topk_ids.is_cuda() && topk_ids.is_contiguous() && topk_ids.scalar_type() == at::kInt &&
              topk_ids.numel() == T * 8, what, ": topk_ids");
  TORCH_CHECK(wr.is_cuda() && wr.is_contiguous() && wr.scalar_type() == at::kByte &&
              wr.numel() == count * ng * eak::NK * static_cast<int64_t>(eak::STAGE_W), what, ": weight records");
  TORCH_CHECK(gs.is_cuda() && gs.is_contiguous() && gs.scalar_type() == at::kFloat && gs.numel() >= count, what, ": gs");
  TORCH_CHECK(err.is_cuda() && err.scalar_type() == at::kInt && err.numel() >= 1, what, ": err");
  TORCH_CHECK(dbg.numel() == 0 || (dbg.is_cuda() && dbg.is_contiguous() && dbg.scalar_type() == at::kLong &&
                                   dbg.numel() >= 2 * grid * eak6::DBG), what, ": dbg");
}

static cudaLaunchConfig_t ea6_cfg(int64_t grid, int smem, bool pdl, cudaLaunchAttribute* attr) {
  cudaLaunchConfig_t cfg{};
  cfg.gridDim = dim3(static_cast<unsigned>(grid));
  cfg.blockDim = dim3(eak6::THREADS);
  cfg.dynamicSmemBytes = static_cast<size_t>(smem);
  cfg.stream = at::cuda::getCurrentCUDAStream();
  attr[0].id = cudaLaunchAttributeProgrammaticStreamSerialization;
  attr[0].val.programmaticStreamSerializationAllowed = 1;
  cfg.attrs = attr;
  cfg.numAttrs = pdl ? 1 : 0;
  return cfg;
}

void ea6_w13(torch::Tensor x, torch::Tensor topk_ids, torch::Tensor wr, torch::Tensor gs, torch::Tensor h,
             torch::Tensor local_ids, torch::Tensor err, torch::Tensor dbg, int64_t T, int64_t start, int64_t count,
             int64_t grid, int64_t minb, int64_t flags) {
  ea6_check(topk_ids, wr, gs, err, dbg, T, count, grid, minb, 128, "ea6_w13");
  TORCH_CHECK(x.is_cuda() && x.is_contiguous() && x.scalar_type() == at::kBFloat16 && x.dim() == 2 &&
              x.size(0) == T && x.size(1) == eak::KDIM, "ea6_w13: x");
  TORCH_CHECK(h.is_cuda() && h.is_contiguous() && h.scalar_type() == at::kBFloat16 && h.numel() >= 32 * T * eak::KDIM,
              "ea6_w13: h");
  TORCH_CHECK(local_ids.is_cuda() && local_ids.is_contiguous() && local_ids.scalar_type() == at::kInt &&
              local_ids.numel() >= T * 8, "ea6_w13: local_ids");
  cudaLaunchAttribute attr[1];
  cudaLaunchConfig_t cfg = ea6_cfg(grid, ea6_req(true, T, flags), (flags & 4) != 0, attr);
  const __nv_bfloat16* xp = reinterpret_cast<const __nv_bfloat16*>(x.data_ptr());
  __nv_bfloat16* hp = reinterpret_cast<__nv_bfloat16*>(h.data_ptr());
  long long* dp = dbg.numel() == 0 ? nullptr : reinterpret_cast<long long*>(dbg.data_ptr());
  const cudaError_t le = minb == 2
      ? cudaLaunchKernelEx(&cfg, eak6::ea6_kernel<true, eak6::D13, 2>, xp, topk_ids.data_ptr<int>(),
                           wr.data_ptr<uint8_t>(), gs.data_ptr<float>(), hp, local_ids.data_ptr<int>(),
                           err.data_ptr<int>(), dp, static_cast<int>(T), static_cast<int>(start),
                           static_cast<int>(count), static_cast<int>(flags))
      : cudaLaunchKernelEx(&cfg, eak6::ea6_kernel<true, eak6::D13, 1>, xp, topk_ids.data_ptr<int>(),
                           wr.data_ptr<uint8_t>(), gs.data_ptr<float>(), hp, local_ids.data_ptr<int>(),
                           err.data_ptr<int>(), dp, static_cast<int>(T), static_cast<int>(start),
                           static_cast<int>(count), static_cast<int>(flags));
  if (le != cudaSuccess) (void)cudaGetLastError();  // do not leave the error for torch's next check
  TORCH_CHECK(le == cudaSuccess, "ea6_w13: launch: ", cudaGetErrorString(le));
}

void ea6_w2(torch::Tensor h, torch::Tensor topk_ids, torch::Tensor wr, torch::Tensor gs, torch::Tensor y,
            torch::Tensor err, torch::Tensor dbg, int64_t T, int64_t start, int64_t count, int64_t grid, int64_t minb,
            int64_t flags) {
  ea6_check(topk_ids, wr, gs, err, dbg, T, count, grid, minb, 64, "ea6_w2");
  TORCH_CHECK(h.is_cuda() && h.is_contiguous() && h.scalar_type() == at::kBFloat16 && h.numel() >= 32 * T * eak::KDIM,
              "ea6_w2: h");
  TORCH_CHECK(y.is_cuda() && y.is_contiguous() && y.scalar_type() == at::kBFloat16 && y.numel() >= T * 8 * eak::KDIM,
              "ea6_w2: y");
  cudaLaunchAttribute attr[1];
  cudaLaunchConfig_t cfg = ea6_cfg(grid, ea6_req(false, T, flags), (flags & 1) != 0, attr);
  const __nv_bfloat16* hp = reinterpret_cast<const __nv_bfloat16*>(h.data_ptr());
  __nv_bfloat16* yp = reinterpret_cast<__nv_bfloat16*>(y.data_ptr());
  long long* dp = dbg.numel() == 0 ? nullptr : reinterpret_cast<long long*>(dbg.data_ptr());
  int* no_ids = nullptr;
  const cudaError_t le = minb == 2
      ? cudaLaunchKernelEx(&cfg, eak6::ea6_kernel<false, eak6::D2, 2>, hp, topk_ids.data_ptr<int>(),
                           wr.data_ptr<uint8_t>(), gs.data_ptr<float>(), yp, no_ids, err.data_ptr<int>(), dp,
                           static_cast<int>(T), static_cast<int>(start), static_cast<int>(count),
                           static_cast<int>(flags))
      : cudaLaunchKernelEx(&cfg, eak6::ea6_kernel<false, eak6::D2, 1>, hp, topk_ids.data_ptr<int>(),
                           wr.data_ptr<uint8_t>(), gs.data_ptr<float>(), yp, no_ids, err.data_ptr<int>(), dp,
                           static_cast<int>(T), static_cast<int>(start), static_cast<int>(count),
                           static_cast<int>(flags));
  if (le != cudaSuccess) (void)cudaGetLastError();
  TORCH_CHECK(le == cudaSuccess, "ea6_w2: launch: ", cudaGetErrorString(le));
}
// ---- end include rewrite/lib/cuda/ea6_kernels.cuh ----
"""


def _ea6_say(s):
    s = s[:199]
    EA6_LINES.append(s)
    print(s, flush=True)


def _ea6_source():
    """_EA2_SRC's #include lines + its ea_common.cuh section + namespace eak of its ea_kernels.cuh section (the whole
    section if the marker is missing) + ea6_kernels.cuh: no text is duplicated in the file."""
    src = _EA2_SRC
    k = src.find("// ---- begin include")
    head = src if k < 0 else src[:k]
    inc = "".join(ln + "\n" for ln in head.splitlines() if ln.startswith("#include "))

    def section(nm):
        b = f"// ---- begin include rewrite/lib/cuda/{nm} ----"
        e = f"// ---- end include rewrite/lib/cuda/{nm} ----"
        i, j = src.find(b), src.find(e)
        if i < 0 or j < i:
            raise RuntimeError(f"{nm} not found in _EA2_SRC")
        return src[i + len(b):j]

    common = section("ea_common.cuh")
    kern = section("ea_kernels.cuh")
    i, end = kern.find("namespace eak {"), "}  // namespace eak"
    j = kern.find(end)
    if i >= 0 and j > i:
        kern = kern[i:j + len(end)] + "\n"
    return inc + common + kern + _EA6_SRC_BODY


def _ea6_build_start(t_prepare):
    """prepare() entry: build the v6 module in a daemon thread (no fd capture: es1a owns fd 1). TORCH_CUDA_ARCH_LIST
    stays 9.0a for all of prepare(), as es1a sets it, so concurrent builds' save / restore can never drop it."""
    import hashlib
    import threading
    os.environ["TORCH_CUDA_ARCH_LIST"] = "9.0a"
    EA6_LINES.clear()
    _EA6_BUILD.clear()
    try:
        src = _ea6_source()
    except Exception as e:
        _EA6_BUILD["result"] = (None, f"source: {type(e).__name__}: {str(e)[:150]}", 0.0)
        return
    name = "okc_campaign_engine_a_v6_" + hashlib.sha256((_EA6_CPP + src).encode()).hexdigest()[:10]
    _EA6_BUILD["name"] = name

    def run():
        try:
            _EA6_BUILD["result"] = _rt_build(EA6_TAG, name, _EA6_CPP, src, ("ea6_info", "ea6_w13", "ea6_w2"))
        except BaseException as e:  # prepare only
            _EA6_BUILD["result"] = (None, f"build thread raised {type(e).__name__}: {str(e)[:150]}", 0.0)

    th = threading.Thread(target=run, name="ea6-build", daemon=True)
    _EA6_BUILD["thread"] = th
    th.start()


def _ea6_build_join(t_prepare):
    """(ext or None, error text, build seconds); joins by EA6_JOIN_S into prepare()."""
    th = _EA6_BUILD.get("thread")
    if th is not None:
        th.join(max(0.0, EA6_JOIN_S - (time.perf_counter() - t_prepare)))
        if th.is_alive():
            return None, f"build not joined by {EA6_JOIN_S:.0f} s", 0.0
    if "result" not in _EA6_BUILD:
        return None, "build not started", 0.0
    return _EA6_BUILD["result"]


def _ea6_forward_core(ea, x, topk_ids, topk_weights, start, count, norm_w, trace=None, pdl13=0, k2_pdl=1, dbg=None,
                      scratch=None):
    """v1's contract: ea6_w13 (h [32, T, I], local_ids), ea6_w2 (y; PDL when k2_pdl), then the CUDA combine if it
    checked out, else the Triton one. dbg / scratch (NaN h, y): prepare only."""
    ext = ea["ext6"]
    tokens, hidden = x.shape
    inter = ea["inter"]
    if scratch is None:
        h = torch.empty((32, tokens, inter), device=x.device, dtype=torch.bfloat16)
        y = torch.empty((tokens * TOP_K, hidden), device=x.device, dtype=torch.bfloat16)
    else:
        h, y = scratch
    local_ids = torch.empty((tokens, TOP_K), device=x.device, dtype=torch.int32)
    d = ea["ea6_nodbg"] if dbg is None else dbg
    grid, minb = ea["ea6_grid"], ea["ea6_minb"]
    if trace is not None:
        trace("before ea6_w13")
    ext.ea6_w13(x, topk_ids, ea["w13r"], ea["gs13"], h, local_ids, ea["err"], d, tokens, start, count, grid, minb,
                4 if pdl13 else 0)
    if trace is not None:
        trace("after ea6_w13 / before ea6_w2")
    ext.ea6_w2(h, topk_ids, ea["w2r"], ea["gs2"], y, ea["err"], d, tokens, start, count, grid, minb,
               (1 | (2 if ea.get("ea6_cores") else 0)) if k2_pdl else 0)  # 2: unpadded K2 beside K1 at T = 1
    if trace is not None:
        trace("after ea6_w2 / before post-expert norm")
    out = torch.empty((tokens, hidden), device=x.device, dtype=torch.bfloat16)
    tw32 = topk_weights.to(torch.float32).contiguous()
    if ea.get("cmb_ok"):  # CUDA twin of the Triton combine (main module), PDL-linked to K2
        ea["ext"].ea_combine(y, local_ids, tw32, norm_w, out, POST_NORM_EPS, 1)
    else:
        _post_norm_combine_kernel[(tokens,)](
            y, local_ids, tw32, norm_w, out, hidden, POST_NORM_EPS,
            TOP_K_C=TOP_K, BLOCK_H=triton.next_power_of_2(hidden), num_warps=8)
    if trace is not None:
        trace("after post-expert norm")
    return out


def _ea6s_forward_core(ea, x, topk_ids, topk_weights, start, count, norm_w, trace=None, pdl13=0, dbg=None,
                       scratch=None):
    """v6s: _ea6_forward_core with K2 launched without the PDL attribute."""
    return _ea6_forward_core(ea, x, topk_ids, topk_weights, start, count, norm_w, trace, pdl13, 0, dbg, scratch)


def _ea6_forced_ids(n, gen, start, count):
    """int32 [1, 8] on the CPU: n distinct local experts plus 8 - n distinct remote ones, shuffled."""
    loc = (torch.randperm(count, generator=gen)[:n] + start).tolist()
    remote = [e for e in range(N_EXPERTS) if not start <= e < start + count]
    rem = [remote[i] for i in torch.randperm(len(remote), generator=gen)[:TOP_K - n].tolist()]
    ids = loc + rem
    return torch.tensor([[ids[i] for i in torch.randperm(TOP_K, generator=gen).tolist()]], dtype=torch.int32)


def _ea6_n_local(ids, start, count):
    return len({int(e) for e in (ids.long() - start).flatten().tolist() if 0 <= e < count})


def _ea6_data(bank, ids, gen, device, hidden):
    tokens = ids.shape[0]
    tw = torch.rand((tokens, TOP_K), generator=gen)
    return {"hidden_states": torch.randn((tokens, hidden), generator=gen).to(torch.bfloat16).to(device),
            "topk_ids": ids.to(device).contiguous(), "topk_weights": (tw / tw.sum(-1, keepdim=True)).to(device),
            "config": _ea_cfg(bank, tokens, hidden)}


def _ea6_canary(weights, bank, state, device, t_prepare):
    """Eager, synced, first launch traced; v6 at T 1..8, v6s at T 1 (spec 4.5 step 2). Returns {arm: [failed T]}."""
    ea = state["ea"]
    start, count = bank["start"], bank["count"]
    hidden, inter = weights["w2"].shape[1], ea["inter"]
    local_set = list(range(start, start + count))
    gen = torch.Generator().manual_seed(EA6_SEED + 1)
    bad = {"v6": [], "v6s": [], "hang": []}   # hang: (arm, T) with a nonzero error word or a raise
    worst = {"v6": 0.0, "v6s": 0.0}
    first = {"v6": True, "v6s": True}
    fail_line = {}
    m_worst, n_in, n_rep = 0.0, 0, 0
    for tokens in range(1, EA_MAX_T + 1):
        rout = _ea_routings(tokens, gen, local_set, device)
        if tokens == 1:
            rout += [(f"forced-n{n}", _ea6_forced_ids(n, gen, start, count).to(device).contiguous()) for n in (3, 4, 5)]
        elif tokens < EA_MAX_T:
            rout = [(lab, ids) for lab, ids in rout if lab in ("zipf", "zero-local", "max-active")]
        arms = ("v6", "v6s") if tokens == 1 else ("v6",)
        for label, ids in rout:
            if time.perf_counter() - t_prepare > EA6_GATE_S:
                for arm in arms:
                    bad[arm].append(tokens)
                fail_line.setdefault("deadline", f"{EA6_TAG} canary stopped at T={tokens}: deadline")
                break
            x = torch.randn((tokens, hidden), generator=gen).to(torch.bfloat16).to(device)
            tw = torch.rand((tokens, TOP_K), generator=gen)
            tw = (tw / tw.sum(-1, keepdim=True)).to(device)
            data = {"hidden_states": x, "topk_ids": ids, "topk_weights": tw, "config": _ea_cfg(bank, tokens, hidden)}
            saved = ea["on"][tokens]
            ea["on"][tokens] = False  # master's own error, as the shared canary measures it
            try:
                master = kernel_fn(data, state).float()
            finally:
                ea["on"][tokens] = saved
            ref = _combo_ref_fp32(weights, bank, state, x, ids, tw)
            torch.cuda.synchronize()
            m_rel = _combo_rel(master, ref)
            m_worst = max(m_worst, m_rel)
            n_act = _ea6_n_local(ids, start, count)
            n_in += 1
            for arm in arms:
                core = _ea6_forward_core if arm == "v6" else _ea6s_forward_core
                reps = 2 if (arm == "v6" and tokens in (1, EA_MAX_T)) else 1
                ea["err"].zero_()
                outs = []
                errw = -1
                try:
                    for _ in range(reps):
                        scratch = (torch.full((32, tokens, inter), float("nan"), device=device, dtype=torch.bfloat16),
                                   torch.full((tokens * TOP_K, hidden), float("nan"), device=device,
                                              dtype=torch.bfloat16))
                        tr = None
                        if first[arm]:
                            print(f"{EA6_TAG} first {arm} launch: T={tokens} {label} (each launch named, synced)",
                                  flush=True)
                            tr = _rt_tracer(EA6_TAG, f"{arm} T={tokens} {label}")
                        outs.append(core(ea, x, ids, tw, start, count, state["post_norm_w"], tr, scratch=scratch))
                        torch.cuda.synchronize()
                        first[arm] = False
                        del scratch
                    errw = int(ea["err"][0])
                    good, rel, row, text = _rt_check(outs[0], ref)
                    good = good and errw == 0 and rel <= 2.0 * max(m_rel, 2e-3)
                    if n_act == 0:
                        good = good and bool((outs[0].float() == 0).all())
                    same = True
                    if reps == 2:
                        n_rep += 1
                        same = bool(torch.equal(outs[0], outs[1]))
                        good = good and same
                    worst[arm] = rel if rel != rel else max(worst[arm], rel)
                    msg = f"{text}, master {m_rel:.3g}, error word {errw}{'' if same else ', REPEAT DIFFERS'}"
                except Exception as e:
                    good, msg = False, f"raised {type(e).__name__}: {str(e)[:120]}"
                if not good and errw != 0:
                    bad["hang"].append((arm, tokens))
                if not good:
                    if tokens not in bad[arm]:
                        bad[arm].append(tokens)
                    ln = f"{EA6_TAG} canary FAIL {arm} T={tokens} {label} (active {n_act}): {msg}"
                    print(ln, flush=True)
                    fail_line.setdefault(arm, ln)
    for ln in fail_line.values():
        _ea6_say(ln)
    parts = []
    for arm, hi in (("v6", EA_MAX_T), ("v6s", 1)):
        parts.append(f"{arm} T1..{hi} " + (f"FAIL at T {bad[arm]}" if bad[arm] else "clean") +
                     f" (worst {worst[arm]:.3g})")
    _ea6_say(f"{EA6_TAG} canary ({n_in} inputs, NaN h/y): " + "; ".join(parts) + f"; master worst {m_worst:.3g}; "
             f"{n_rep} bitwise repeats")
    return bad


def _ea6_kernel_only(weights, bank, state, device):
    """K1 / K2 alone at T = 1, forced n = 2 / 3: v1's (if it is the incumbent) and v6's (K2 plain). One line."""
    ea = state["ea"]
    ext, ext6 = ea["ext"], ea["ext6"]
    start, count, inter = bank["start"], bank["count"], ea["inter"]
    hidden = weights["w2"].shape[1]
    grid6, minb, nodbg = ea["ea6_grid"], ea["ea6_minb"], ea["ea6_nodbg"]
    gen = torch.Generator().manual_seed(EA6_SEED + 2)
    parts = []
    for n in (2, 3):
        ids = _ea6_forced_ids(n, gen, start, count).to(device).contiguous()
        x = torch.randn((1, hidden), generator=gen).to(torch.bfloat16).to(device)
        h = torch.zeros((32, 1, inter), dtype=torch.bfloat16, device=device)
        lid = torch.empty((1, TOP_K), dtype=torch.int32, device=device)
        y = torch.empty((TOP_K, hidden), dtype=torch.bfloat16, device=device)
        graphs = {}
        if ea["on"].get(1) == "v1":  # as _ea_forward_core runs it at T = 1: w2 L2 prefetch if pf_t, K2 on g2_t
            pf = ea.get("pf_t", {}).get(1, 0)
            if pf:
                graphs["v1K1"], _ = _rt_graph(lambda: ext.ea_w13_pf(x, ids, ea["w13r"], ea["gs13"], h, lid, ea["ws13"],
                                                                    ea["tk13"], ea["err"], 1, start, count, ea["grid"],
                                                                    ea["dq"], 0, ea["w2r"], pf))
            else:
                graphs["v1K1"], _ = _rt_graph(lambda: ext.ea_w13(x, ids, ea["w13r"], ea["gs13"], h, lid, ea["ws13"],
                                                                 ea["tk13"], ea["err"], 1, start, count, ea["grid"],
                                                                 ea["dq"], 0))
            g2 = ea.get("g2_t", {}).get(1, ea["grid"])
            graphs["v1K2"], _ = _rt_graph(lambda: ext.ea_w2(h, ids, ea["w2r"], ea["gs2"], y, ea["ws2"], ea["tk2"],
                                                            ea["err"], 1, start, count, g2, ea["dq"], 0))
        graphs["v6K1"], _ = _rt_graph(lambda: ext6.ea6_w13(x, ids, ea["w13r"], ea["gs13"], h, lid, ea["err"], nodbg,
                                                          1, start, count, grid6, minb, 0))
        graphs["v6K2"], _ = _rt_graph(lambda: ext6.ea6_w2(h, ids, ea["w2r"], ea["gs2"], y, ea["err"], nodbg, 1, start,
                                                         count, grid6, minb, 0))
        r = _rt_time(graphs, device, reps=21, rounds=1)
        torch.cuda.synchronize()
        parts.append(f"n{n} " + " ".join(f"{k} {_rt_stats(r[0][k])[0]:.2f}" for k in graphs))
        del graphs
    _ea6_say(f"{EA6_TAG} kernel-only T=1 us (K2 plain): " + "; ".join(parts))


def _ea6_race(bank, state, device, cls, inputs, arms, hidden, seed):
    """kernel_fn graphs of the incumbent ('inc') and each arm per input [(label, ids)]: {label: _rt_time rounds}."""
    ea = state["ea"]
    inc = ea["on"][cls]
    gen = torch.Generator().manual_seed(seed)
    per = {}
    try:
        for label, ids in inputs:
            data = _ea6_data(bank, ids, gen, device, hidden)
            graphs = {}
            for name in ("inc",) + tuple(arms):
                ea["on"][cls] = inc if name == "inc" else name
                graphs[name], _ = _rt_graph(lambda: kernel_fn(data, state))
            ea["on"][cls] = inc
            per[label] = _rt_time(graphs, device)
            torch.cuda.synchronize()
            del graphs
    finally:
        ea["on"][cls] = inc
    return per


def _ea6_judge(per, specs, arms):
    """specs [(label, weight, floor)]: per arm and round the weighted mean of incumbent / arm medians; qualifies if every
    round has every input >= its floor and wr >= RT_MARGIN (or RT_MARGIN_TIGHT_IQR with every arm IQR tight)."""
    res = {}
    for arm in arms:
        rr = []
        for ri in range(RT_ROUNDS):
            num = wsum = 0.0
            floor_ok = iqr_ok = True
            fmin, fwhere = float("inf"), ""
            med = {}
            for label, wgt, floor in specs:
                ts = per[label][ri]
                im, ii = _rt_stats(ts["inc"])[:2]
                am, ai = _rt_stats(ts[arm])[:2]
                med[label] = (im, am)
                ratio = im / max(am, 1e-3)
                if ratio - floor < fmin:
                    fmin, fwhere = ratio - floor, label
                floor_ok = floor_ok and ratio >= floor
                iqr_ok = iqr_ok and ai <= RT_IQR_FACTOR * max(ii, RT_IQR_FLOOR_US)
                num += wgt * ratio
                wsum += wgt
            wr = num / max(wsum, 1e-12)
            ok = floor_ok and (wr >= RT_MARGIN or (wr >= RT_MARGIN_TIGHT_IQR and iqr_ok))
            rr.append({"wr": wr, "ok": ok, "fmin": fmin, "fwhere": fwhere, "iqr": iqr_ok, "med": med})
        res[arm] = {"rounds": rr, "ok": all(r["ok"] for r in rr), "worst": min(r["wr"] for r in rr)}
    return res


def _ea6_slopes(t):
    """[t(n=2), t(3), t(4), t(5)] -> (steps 2>3, 3>4, 4>5, OLS slope over n = 2..5), us per extra local expert."""
    return t[1] - t[0], t[2] - t[1], t[3] - t[2], (-1.5 * t[0] - 0.5 * t[1] + 0.5 * t[2] + 1.5 * t[3]) / 5.0


def _ea6_class1(bank, state, device, arms, hidden):
    """T = 1 race on forced n = 1..5 (weights EA6_W1, floors EA6_FLOOR): the winner or None."""
    ea = state["ea"]
    start, count = bank["start"], bank["count"]
    inc = ea["on"][1]
    gen = torch.Generator().manual_seed(EA6_SEED)
    inputs = [(f"n{n}", _ea6_forced_ids(n, gen, start, count)) for n in range(1, 6)]
    per = _ea6_race(bank, state, device, 1, inputs, arms, hidden, EA6_SEED + 3)
    specs = [(f"n{n}", EA6_W1.get(n, 0.0), EA6_FLOOR[n]) for n in range(1, 6)]
    res = _ea6_judge(per, specs, arms)
    names = ("inc",) + tuple(arms)
    for ri in range(RT_ROUNDS):
        med = {nm: [_rt_stats(per[f"n{n}"][ri][nm])[0] for n in range(1, 6)] for nm in names}
        _ea6_say(f"{EA6_TAG} T=1 us n1..n5 r{ri + 1}: " + " | ".join(
            f"{'inc(' + str(inc or 'master') + ')' if nm == 'inc' else nm} " + "/".join(f"{v:.1f}" for v in med[nm])
            for nm in names))
        _ea6_say(f"{EA6_TAG} T=1 us per extra expert r{ri + 1} (2>3/3>4/4>5/OLS2-5): " + " | ".join(
            f"{nm} " + "/".join(f"{v:.2f}" for v in _ea6_slopes(med[nm][1:5])) for nm in names))
    good = [a for a in arms if res[a]["ok"]]
    win = max(good, key=lambda a: res[a]["worst"]) if good else None
    parts = []
    for a in arms:
        lo = min(res[a]["rounds"], key=lambda r: r["fmin"])
        parts.append(f"{a} wr " + "/".join(f"{r['wr']:.3f}" for r in res[a]["rounds"]) +
                     f" floor margin {lo['fmin']:+.3f}@{lo['fwhere']}" + (" Q" if res[a]["ok"] else " -"))
    _ea6_say(f"{EA6_TAG} T=1 vs {inc or 'master'}: " + " | ".join(parts) + f" -> {win or 'incumbent'}")
    return win


def _ea6_class8(bank, state, device, hidden):
    """T = 8 race on reference-style draws 1 / 7 / 13 of 15 by distinct local experts: 'v6' or None."""
    ea = state["ea"]
    start, count = bank["start"], bank["count"]
    inc = ea["on"][8]
    gen = torch.Generator().manual_seed(EA6_SEED + 8)
    draws = []
    for _ in range(15):
        ids = _eb_ref_ids(8, gen, "normal", start, count)
        draws.append((_ea6_n_local(ids, start, count), ids))
    draws.sort(key=lambda d: d[0])
    inputs = [(f"{tag} n={draws[i][0]}", draws[i][1]) for tag, i in (("p10", 1), ("p50", 7), ("p90", 13))]
    per = _ea6_race(bank, state, device, 8, inputs, ("v6",), hidden, EA6_SEED + 9)
    specs = [(lab, 1.0, EA6_FLOOR8) for lab, _ in inputs]
    res = _ea6_judge(per, specs, ("v6",))
    rr = res["v6"]["rounds"]
    win = "v6" if res["v6"]["ok"] else None
    _ea6_say(f"{EA6_TAG} T=8 us {'/'.join(lab for lab, _ in inputs)}: " + " ; ".join(
        f"r{ri + 1} inc({inc or 'master'}) " + "/".join(f"{r['med'][lab][0]:.1f}" for lab, _ in inputs) +
        " v6 " + "/".join(f"{r['med'][lab][1]:.1f}" for lab, _ in inputs) for ri, r in enumerate(rr)))
    _ea6_say(f"{EA6_TAG} T=8 vs {inc or 'master'}: v6 wr " + "/".join(f"{r['wr']:.3f}" for r in rr) +
             f" floor margin {min(r['fmin'] for r in rr):+.3f}{' Q' if win else ' -'} -> {win or 'incumbent'}")
    return win


def _ea6_anat_one(d, G):
    """Per-CTA phases (us) from a debug buffer d (int64 [2, G, 8], globaltimer ns)."""
    k1, k2 = d[0].double(), d[1].double()
    w1, w2 = k1[:, 4] > 0, k2[:, 4] > 0
    if not bool(w1.any()) or not bool(w2.any()):
        return None
    med = lambda v: float(v.median())  # noqa: E731
    k1end = float(k1[w1, 3].max())
    return {"ramp": med(k1[w1, 1] - k1[w1, 0]) / 1e3,
            "rec1": med((k1[w1, 2] - k1[w1, 1]) / (k1[w1, 4] - 1).clamp_min(1)) / 1e3,
            "spread": float(k1[w1, 3].max() - k1[w1, 3].min()) / 1e3,
            "entry": med(k2[w2, 0] - k1end) / 1e3,
            "wait": med(k2[w2, 5] - k1end) / 1e3,
            "first": med(k2[w2, 1] - k1end) / 1e3,
            "rec2": med((k2[w2, 2] - k2[w2, 1]) / (k2[w2, 4] - 1).clamp_min(1)) / 1e3,
            "tail": float(k2[w2, 3].max() - k2[w2, 3].median()) / 1e3,
            "early": float((k2[w2, 0] < k1end).double().mean()) * 100.0,
            "span": float(k2[w2, 3].max() - k1[:, 0].min()) / 1e3}


def _ea6_anatomy(weights, bank, state, device, arms):
    """Diagnostic only: v6 / v6s at T = 1, n = 2 / 3, eager, synced, inputs held; median phases of 3 runs."""
    ea = state["ea"]
    start, count, hidden = bank["start"], bank["count"], weights["w2"].shape[1]
    G = ea["ea6_grid"]
    dbg = torch.zeros(2 * G * EA6_DBG, dtype=torch.int64, device=device)
    gen = torch.Generator().manual_seed(EA6_SEED + 4)
    keep = []
    for n in (2, 3):
        ids = _ea6_forced_ids(n, gen, start, count).to(device).contiguous()
        x = torch.randn((1, hidden), generator=gen).to(torch.bfloat16).to(device)
        tw = torch.full((1, TOP_K), 1.0 / TOP_K, dtype=torch.float32, device=device)
        keep.append((ids, x, tw))
        for arm in arms:
            core = _ea6_forward_core if arm == "v6" else _ea6s_forward_core
            runs = []
            for _ in range(3):
                _rt_read_flush(device)
                dbg.zero_()
                o = core(ea, x, ids, tw, start, count, state["post_norm_w"], dbg=dbg)
                torch.cuda.synchronize()
                keep.append(o)
                a = _ea6_anat_one(dbg.view(2, G, EA6_DBG).cpu(), G)
                if a is not None:
                    runs.append(a)
            if not runs:
                _ea6_say(f"{EA6_TAG} anatomy {arm} n{n}: no CTA timestamps")
                continue
            m = {k: sorted(r[k] for r in runs)[len(runs) // 2] for k in runs[0]}
            _ea6_say(f"{EA6_TAG} anatomy {arm} n{n} us: K1 ramp {m['ramp']:.2f} rec {m['rec1']:.2f} spread "
                     f"{m['spread']:.2f} | K2 vs K1 end: entry {m['entry']:+.1f} wait {m['wait']:+.2f} first "
                     f"{m['first']:+.2f}, rec {m['rec2']:.2f} tail {m['tail']:.2f} | early {m['early']:.0f}% "
                     f"span {m['span']:.1f}")
    torch.cuda.synchronize()
    del keep


def _ea6_copy_check(weights, bank, state, device, tokens, arm):
    """kernel_fn graphs with arm at T = tokens on this state and a _wg_copy_tree copy, 4 refills in alternating order,
    each vs eager (rel-L2 <= EA_COPY_TOL); ea['on'] restored. Returns (ok, text)."""
    ea = state["ea"]
    start, count, hidden = bank["start"], bank["count"], weights["w2"].shape[1]
    local_set = list(range(start, start + count))
    inc = ea["on"][tokens]
    gen = torch.Generator().manual_seed(EA6_SEED + 5)
    fails, n = [], 0
    ea["on"][tokens] = arm
    try:
        other = _wg_copy_tree(state)
        cfg = _ea_cfg(bank, tokens, hidden)
        per = []
        for st in (state, other):
            data = {"hidden_states": torch.zeros((tokens, hidden), dtype=torch.bfloat16, device=device),
                    "topk_ids": torch.full((tokens, TOP_K), start, dtype=torch.int32, device=device),
                    "topk_weights": torch.full((tokens, TOP_K), 1.0 / TOP_K, dtype=torch.float32, device=device),
                    "config": cfg}
            graph, out = _rt_graph(lambda data=data, st=st: kernel_fn(data, st))
            per.append((data, graph, out))
        rd = dict(_ea_routings(tokens, gen, local_set, device))
        routs = [rd["zipf"], rd["skewed-4hot"]] * 2  # the shared check's refills ...
        if tokens == 1:  # ... and at T = 1 also the judge's commonest n = 2 / 3
            routs[2:] = [_ea6_forced_ids(k, gen, start, count).to(device) for k in (2, 3)]
        for k in range(4):
            ids = routs[k]
            x = torch.randn((tokens, hidden), generator=gen).to(torch.bfloat16).to(device)
            tw = torch.rand((tokens, TOP_K), generator=gen).to(device)
            for data, _, _ in per:
                data["hidden_states"].copy_(x)
                data["topk_ids"].copy_(ids)
                data["topk_weights"].copy_(tw)
            for _, graph, _ in (per if k % 2 == 0 else per[::-1]):
                graph.replay()
            torch.cuda.synchronize()
            ref = kernel_fn({"hidden_states": x, "topk_ids": ids, "topk_weights": tw, "config": cfg}, state).float()
            torch.cuda.synchronize()
            for i, (_, _, out) in enumerate(per):
                n += 1
                rel = _combo_rel(out.float(), ref)
                if not rel <= EA_COPY_TOL:
                    fails.append(f"state {'AB'[i]} refill {k}: rel-L2 vs eager {rel:.3g}")
        del per, other
    finally:
        ea["on"][tokens] = inc
        torch.cuda.synchronize()
        gc.collect()
        torch.cuda.empty_cache()
    return not fails, (f"{EA6_TAG} copy check {arm} T={tokens}: {n} replays on two states: " +
                       ("PASS" if not fails else f"FAIL ({fails[0]})"))


def _ea6_stage(weights, bank, state, device, t_prepare):
    """v6's admission, canary, kernel-only, races, anatomy, copy check and routing. Never raises (ea['on'] restored);
    a missed deadline skips a step and keeps the incumbents. Lines go to EA6_LINES."""
    ea = state["ea"]
    prev = dict(ea["on"])
    t0 = time.perf_counter()
    EA6_LINES.clear()
    hidden = weights["w2"].shape[1]

    def late(limit):
        return time.perf_counter() - t_prepare > limit

    try:
        if late(EA6_START_S):
            _ea6_say(f"{EA6_TAG} skipped: deadline (start at {time.perf_counter() - t_prepare:.1f} s > {EA6_START_S:.0f})")
            return [EA6_LINES[-1]]
        if ea.get("dq") != 2:
            _ea6_say(f"{EA6_TAG} skipped: dq {ea.get('dq')} (v6 is dq2 only)")
            return [EA6_LINES[-1]]
        ext6, err_text, dt = _ea6_build_join(t_prepare)
        if ext6 is None:
            _ea6_say(f"{EA6_TAG} build FAILED: {str(err_text)[:170]}")
            return [EA6_LINES[-1]]
        info = [int(v) for v in ext6.ea6_info()]
        rows = [info[6 * i:6 * i + 6] for i in range(4)]   # K1 m2, K1 m1, K2 m2, K2 m1: ok regs lmem s1 s8 occ
        usable = [bool(r[0]) and r[5] >= 1 for r in rows]
        if usable[0] and usable[2] and rows[0][2] == 0 and rows[2][2] == 0:
            minb = 2
        elif usable[1] and usable[3]:
            minb = 1
        else:
            _ea6_say(f"{EA6_TAG} build {dt:.1f} s: no usable instance (attrs/occupancy {rows})")
            return [EA6_LINES[-1]]
        alloc = lambda r: -(-32 * r // 256) * 256  # noqa: E731  (registers per warp, 256-register granules)
        r13, r2 = rows[0 if minb == 2 else 1], rows[2 if minb == 2 else 3]
        cores = minb == 2 and 10 * alloc(r13[1]) + 10 * alloc(r2[1]) <= 65536
        sms = int(torch.cuda.get_device_properties(device).multi_processor_count)
        ea.update({"ext6": ext6, "ea6_minb": minb, "ea6_grid": sms, "ea6_cores": cores,
                   "ea6_nodbg": torch.empty(0, dtype=torch.int64, device=device)})
        spill = "" if minb == 2 or (rows[1][2] == 0 and rows[3][2] == 0) else " SPILL at both MINB"
        _ea6_say(f"{EA6_TAG} build {dt:.1f} s (regs/lmem B/occ): " + " ".join(
            f"{nm}m{mb} {r[1]}/{r[2]}/{r[5]}" for nm, mb, r in
            (("K1", 2, rows[0]), ("K1", 1, rows[1]), ("K2", 2, rows[2]), ("K2", 1, rows[3]))) +
            f"; MINB {minb}{spill}; grid {sms}; K2 co-resident at T=1: {'yes' if cores else 'no'}")
        if late(EA6_GATE_S):
            _ea6_say(f"{EA6_TAG} canary skipped: deadline -> incumbents kept")
            return [EA6_LINES[-1]]
        bad = _ea6_canary(weights, bank, state, device, t_prepare)
        arms1 = tuple(a for a in ("v6", "v6s") if 1 not in bad[a])
        ok8 = not any(2 <= t <= EA_MAX_T for t in bad["v6"])
        hang1 = any(t == 1 for _, t in bad["hang"])
        if hang1:
            _ea6_say(f"{EA6_TAG} kernel-only skipped: T=1 canary saw an error word or a raise")
        elif not late(EA6_GATE_S):
            try:  # diagnostic only (also when the canary failed on numbers alone)
                _ea6_kernel_only(weights, bank, state, device)
            except Exception as e:
                _ea6_say(f"{EA6_TAG} kernel-only raised {type(e).__name__}: {str(e)[:150]}")
        win = {1: None, 8: None}
        if not arms1:
            _ea6_say(f"{EA6_TAG} T=1 race skipped: no canary-clean arm -> incumbent")
        elif late(EA6_GATE_S):
            _ea6_say(f"{EA6_TAG} T=1 race skipped: deadline -> incumbent")
        else:
            try:  # a raise loses this class only
                win[1] = _ea6_class1(bank, state, device, arms1, hidden)
            except Exception as e:
                ea["on"][1] = prev[1]
                _ea6_say(f"{EA6_TAG} T=1 race raised {type(e).__name__}: {str(e)[:150]} -> incumbent")
        if EA_PIN.get(8) and ea["on"].get(8) == EA_PIN[8]:  # only when the pin took (v4 canary-clean)
            _ea6_say(f"{EA6_TAG} T=8 race skipped: class 8 PINNED to {EA_PIN[8]} (EA_PIN) -> incumbent")
        elif not ok8:
            _ea6_say(f"{EA6_TAG} T=8 race skipped: canary FAIL at T 2..8 -> incumbent")
        elif late(EA6_GATE_S):
            _ea6_say(f"{EA6_TAG} T=8 race skipped: deadline -> incumbent")
        else:
            try:  # a raise loses this class only
                win[8] = _ea6_class8(bank, state, device, hidden)
            except Exception as e:
                ea["on"][8] = prev[8]
                _ea6_say(f"{EA6_TAG} T=8 race raised {type(e).__name__}: {str(e)[:150]} -> incumbent")
        if EA6_ANATOMY and arms1 and not late(EA6_GATE_S):
            try:  # diagnostic only
                _ea6_anatomy(weights, bank, state, device, arms1)
            except Exception as e:
                _ea6_say(f"{EA6_TAG} anatomy raised {type(e).__name__}: {str(e)[:150]}")
        for cls in EA6_CLASSES:
            # class 8 routes T = 2..8: check its largest and smallest T, as the shared check will (picks per engine)
            for tc in ((1,) if cls == 1 else (EA_MAX_T, 2)):
                if win[cls] is None:
                    break
                if late(EA6_COPY_S):
                    _ea6_say(f"{EA6_TAG} copy check {win[cls]} T={tc}: skipped: deadline -> incumbent")
                    win[cls] = None
                    break
                try:
                    ok_, text = _ea6_copy_check(weights, bank, state, device, tc, win[cls])
                except Exception as e:
                    ea["on"][tc] = prev[tc]
                    ok_ = False
                    text = f"{EA6_TAG} copy check {win[cls]} T={tc} raised {type(e).__name__}: {str(e)[:120]}"
                _ea6_say(text)
                if not ok_:
                    win[cls] = None
        if win[1] is not None:
            ea["on"][1] = win[1]
        if win[8] is not None:
            for t in range(2, EA_MAX_T + 1):
                ea["on"][t] = win[8]
        _ea6_say(f"{EA6_TAG} route: T=1 {ea['on'][1] or 'master'}" + (" (v6 family)" if win[1] else " (incumbent)") +
                 f"; T=2..8 {ea['on'][8] or 'master'}" + (" (v6)" if win[8] else " (incumbent)") +
                 f"; stage {time.perf_counter() - t0:.1f} s, prepare at {time.perf_counter() - t_prepare:.1f} s")
    except Exception as e:  # prepare only: the incumbents stay
        ea["on"].clear()
        ea["on"].update(prev)
        _ea6_say(f"{EA6_TAG} stage raised {type(e).__name__}: {str(e)[:150]} -> incumbents kept")
    try:
        ea["err"].zero_()
        torch.cuda.synchronize()
    except Exception as e:
        _ea6_say(f"{EA6_TAG} final sync raised {type(e).__name__}: {str(e)[:150]}")
    return [f"{EA6_TAG} stage done in {time.perf_counter() - t0:.1f} s ({len(EA6_LINES)} lines, printed last)"]


def _ea6_final_lines(state):
    """EA6_LINES, Engine A's PATH CHOSEN lines and the shared copy check line, each <= 199 chars."""
    out = list(EA6_LINES) if EA6_LINES else [f"{EA6_TAG} stage did not run (Engine A setup ended before it)"]
    ea = state.get("ea") or {}
    on = ea.get("on")
    if on:
        out.extend(_ea_moe_path_lines(ea))
    if ea.get("copy_line"):
        out.append(ea["copy_line"])
    return [ln[:199] for ln in out]
